  // munge of answerActor.sen
  sDefinition =
    "\""
    "\\\"munged answerActor.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* AnswerActor.sen -- answer actor                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"AnswerTask.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* declare connections variable to keep the number of connections             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "int: nConnections\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* start the answer task                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": answerStart\n"
    "\n"
    "  0 \\\"ans.loop\\\" nullPtr \\\"answerTask\\\" spawnActorTask\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* answer loop                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ans.loop\n"
    "\n"
    "  // get the listening port of this node\n"
    "  grid.thisNode@ grid.node node.port locals| iPort |\n"
    "\n"
    "  answerTaskPrint if \\\"Answer running...\\\" . then\n"
    "\n"
    "  args.verbose if\n"
    "    \\\"waiting for connections on port \\\"  iPort >str str.cat .\n"
    "    iPort >str \\\"Listening on port \\\" swap str.cat .\n"
    "  then\n"
    "\n"
    "  iPort socket.listen locals| pListeningSocket |\n"
    "\n"
    "  0 nConnections !\n"
    "  begin\n"
    "\n"
    "tp: waitingOnAccept\n"
    "\n"
    "    pListeningSocket socket.accept\n"
    "\n"
    "tp: socketAccepted\n"
    "\n"
    "    args.verbose if\n"
    "      \\\"accepted connection on port \\\" iPort >str str.cat .\n"
    "    then\n"
    "\n"
    "  // start receiver\n"
    "  //\\\"starting receiver\\\" .\n"
    "\n"
    "ddlLock::grabWrite\n"
    "\n"
    "    // set up the seed\n"
    "    1 \\\"rcv.loop\\\" ( socket 1 \\\"rcv.loop\\\" )\n"
    "\n"
    "    // create the actor\n"
    "    \\\"rr\\\" nConnections @ >str str.cat ( socket 1 \\\"rcv.loop\\\" \\\"rrI\\\" )\n"
    "    :job ( socket 1 \\\"rcv.loop\\\" \\\"rrI\\\" )\n"
    "\n"
    "    // spawn the actors os thread\n"
    "    job.spawn\n"
    "\n"
    "ddlLock::dropWrite\n"
    "\n"
    "    nConnections @          ( connection# )\n"
    "    1 +                    ( nConnections# 1 )\n"
    "    dup                    ( nConnections# nConnections# )\n"
    "    nConnections !          ( nConnections# )\n"
    "\n"
    "    1  == if               ( connection# )\n"
    "      grid.thisNode@ grid.startNode@ != if\n"
    "        connectorStart\n"
    "      then\n"
    "    then\n"
    "      \n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT answerActor.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of answerDrone.sen
  sDefinition =
    "\""
    "\\\"munged answerDrone.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* AnswerDrone.sen -- answer drone                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"AnswerDrone.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* declare connections variable to keep the number of connections             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "int: nConnections\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn the answer drone                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnAnswerDrone\n"
    "\n"
    "  0 \\\"answerLoop\\\" \\\"AnswerDrone\\\" TK_ANSWER_DRONE spawnDroneActor\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* accept new sockets, spawning a worker actor for each new socket            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": answerLoop\n"
    "\n"
    "  answerDronePrint if\n"
    "    task::this task.name@ \\\" running...\\\" str.cat .\n"
    "  then\n"
    "\n"
    "  // get the listening port of this node\n"
    "  grid.thisNode@ grid.node node.port locals| iPort |\n"
    "\n"
    "  args.verbose if\n"
    "    \\\"waiting for connections on port \\\"  iPort >str str.cat .\n"
    "    iPort >str \\\"Listening on port \\\" swap str.cat .\n"
    "  then\n"
    "\n"
    "  iPort socket.listen locals| pListeningSocket |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  0 nConnections !\n"
    "  begin\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // wait for next socket\n"
    "\n"
    "    tp: waitingOnAccept\n"
    "\n"
    "    pListeningSocket socket.accept\n"
    "\n"
    "    tp: socketAccepted\n"
    "\n"
    "    args.verbose if\n"
    "      \\\"answered connection on port \\\" iPort >str str.cat .\n"
    "    then\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // start receiver drone for the new socket\n"
    "\n"
    "    ddlLock::grabWrite\n"
    "\n"
    "    // set up the seed\n"
    "    1 \\\"receiverLoop\\\" ( socket 1 \\\"receiverLoop\\\" )\n"
    "\n"
    "    // form name of the receiver\n"
    "    \\\"rr\\\" nConnections @ >str str.cat ( socket 1 \\\"receiverLoop\\\" \\\"rrI\\\" )\n"
    "\n"
    "    // spawn the actors os thread\n"
    "    TK_RECEIVER_DRONE spawnDroneActor\n"
    "\n"
    "    ddlLock::dropWrite\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // increment connection counter\n"
    "\n"
    "    nConnections @          ( connection# )\n"
    "    1 +                    ( nConnections# 1 )\n"
    "    dup                    ( nConnections# nConnections# )\n"
    "    nConnections !          ( nConnections# )\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // if very first socket start connector drone\n"
    "\n"
    "    1 == if               ( connection# )\n"
    "      grid.thisNode@ grid.startNode@ != if\n"
    "        spawnConnectorDrone assert\n"
    "      then\n"
    "    then\n"
    "      \n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT answerDrone.sen"_Stz
  ;

  vCompileConstant(sDefinition);

