  // munge of catalog.sen
  sDefinition =
    "\""
    "\\\"munged catalog.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* catalog.sen -- catalog related words                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"catalog.sen\\\" .verbose\n"
    "\n"
    ": catalog ;\n"
    "\n"
    ": :catalog\n"
    "    :dic\n"
    "         //dup tick catalog swap word.kind!\n"
    "         dup tick catalog swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinCatalogs\n"
    "    0 pathPick dic.name \\\"catalogs\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInCatalogs\n"
    "    withinCatalogs if true exit then\n"
    "    EC_NOT_IN_CATALOGS false\n"
    " ;\n"
    "\n"
    ": checkIsCatalog ( word )\n"
    "\n"
    "    dup word.kind@ tick folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "    dup execute dic.kind@ tick catalog eql if true exit then\n"
    "    EC_NOT_A_CATALOG false\n"
    " ;\n"
    "\n"
    ": checkIsNotCatalog ( word )\n"
    "    dup findInCurrent not if true exit then\n"
    "    EC_CATALOG_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable tenant folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeCatalog ( \\\"<catalogNm>\\\" -- \\\"<catalogNm>\\\" true | \\\"<catalogNm>\\\" errorCode false )\n"
    "\n"
    "  checkInCatalogs   not if false exit then\n"
    "  checkIsNotCatalog not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable catalog folder                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveCatalog ( \\\"<catalogNm>\\\" -- \\\"<catalogNm>\\\" true | \\\"<catalogNm>\\\" errorCode false )\n"
    "\n"
    "  dup ( \\\"<catalogNm>\\\" \\\"<catalogNm>\\\" )\n"
    "\n"
    "  checkInCatalogs not if false exit then ( \\\"<catalogNm>\\\" word )\n"
    "  checkIsWord     not if false exit then ( \\\"<catalogNm>\\\" word )\n"
    "  checkIsCatalog  not if false exit then ( \\\"<catalogNm>\\\" word )\n"
    "  checkIsEmpty    not if false exit then ( \\\"<catalogNm>\\\" word )\n"
    "  checkNotUsed    not if false exit then ( \\\"<catalogNm>\\\" word )\n"
    "\n"
    "  drop ( \\\"<catalogNm>\\\" )\n"
    "\n"
    "  true ( \\\"<catalogNm>\\\" true )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a catalogs folder under given named tenant                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeCatalogs ( \\\"<tenantNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING CATALOGS FOR TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"catalogs\\\"   ( dic \\\"catalogs\\\" )\n"
    "  swap         ( \\\"catalogs\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a named catalog folder (run by participant)                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeCatalog allParticipants 1 checkResult ( \\\"<catalogNm>\\\" -- true n# true )\n"
    "\n"
    "tp: makeCatalog\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING CATALOG \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<catalogNm>\\\" \\\"<catalogNm>\\\" )\n"
    "\n"
    "  :catalog ( \\\"<catalogNm>\\\" ^catalog )\n"
    "\n"
    "  drop ( \\\"<catalogNm>\\\" )\n"
    "\n"
    "  makeSchemas ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a catalog folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeCatalog allParticipants 1 checkResult ( \\\"<catalogNm>\\\" -- true n# true )\n"
    "\n"
    "tp: removeCatalog\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"REMOVING CATALOG \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  :forget ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT catalog.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of column.sen
  sDefinition =
    "\""
    "\\\"munged column.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* column.sen -- column related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"column.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* column is used as a kind of word to identify index columns                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": column: ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the tables columns sub folder                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeColumns ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  find execute ( dic )\n"
    "  table.subDic pathPush \\\"columns\\\" :dic drop pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within table columns folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinColumns\n"
    "    0 pathPick dic.name \\\"columns\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInColumns\n"
    "    withinColumns if true exit then\n"
    "    EC_NOT_IN_COLUMNS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushColumns ( -- )\n"
    "    \\\"columns\\\" checkIsWord\n"
    "    not if EC_NO_COLUMNS_DIC false exit then\n"
    "    execute pathPush\n"
    "    true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table column folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popColumns\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create table column as a constant                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :column ( \\\"<columnType>\\\" \\\"<columnName>\\\" )\n"
    "    :constant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check and add a table column                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAddColumn ( \\\"<columnName>\\\" \\\"<tableNm>\\\" -- true | eEC false )\n"
    "\n"
    "  locals| tableNm columnNm |\n"
    "\n"
    "  tableNm checkInTable not if false exit then\n"
    "\n"
    "  tableNm\n"
    "  pushTableSub   assert // not if false exit then\n"
    "\n"
    "  columnNm\n"
    "  pushColumns assert // not if false exit then\n"
    "\n"
    "  // column should not already exist\n"
    "  findInCurrent\n"
    "  if EC_DUPLICATE_COLUMN false popColumns popTable exit then\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listColumns ( -- )\n"
    "\n"
    "  0 locals| count |\n"
    "\n"
    "  pushTableSub  assert\n"
    "  pushColumns   assert\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"\\\"                             // initial ls string\n"
    "    0 pathPick dic.lastWord        // get last word of current dic\n"
    "    dup                            // setup iteration of words\n"
    "    iterate                        //\n"
    "\n"
    "      1 count + to count\n"
    "\n"
    "      object@ word.name            // column name\n"
    "\n"
    "      \\\"row: ('\\\" swap str.cat\n"
    "      \\\" \\\" str.cat\n"
    "      object@ execute str.cat       // column type\n"
    "\n"
    "      swap\n"
    "\n"
    "      \\\"')\\\\n\\\" str.prepend            //\n"
    "\n"
    "      str.cat                       // append column to ls\n"
    "\n"
    "      object@ word.prev object!     // step backwards thru words\n"
    "\n"
    "    next                            //\n"
    "    count task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "    \\\"\\\"                               // initial ls string\n"
    "    0 pathPick dic.lastWord          // get last word of current dic\n"
    "      dup                            // setup iteration of words\n"
    "      iterate                        //\n"
    "\n"
    "      object@ word.name            // column name\n"
    "\n"
    "      \\\" \\\" str.cat\n"
    "      object@ execute str.cat       // column type\n"
    "\n"
    "      swap\n"
    "\n"
    "      dup str.length\n"
    "      if \\\" , \\\" str.prepend then     //\n"
    "\n"
    "      str.cat                       // append column to ls\n"
    "\n"
    "      object@ word.prev object!     // step backwards thru words\n"
    "\n"
    "    next                            //\n"
    "\n"
    "  then\n"
    "\n"
    "  //\\\"\\\\n\\\" str.cat\n"
    "\n"
    "  popColumns\n"
    "  popTableSub\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add a column (run by all participants)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addColumn allParticipants 3 checkResult ( \\\"<columnType>\\\" \\\"<columnNm>\\\" \\\"<tableNm>\\\" -- <result> )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"ADDING COLUMN \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tp: addingColumn\n"
    "  pushTableSub   assert // not if false exit then\n"
    "\n"
    "  pushColumns assert // not if false exit then\n"
    "\n"
    "  :column\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the table                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecTable allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "  0 locals| tablePtr tableNm |\n"
    "\n"
    "  //\\\"columnVecTable\\\" . tableNm .\n"
    "\n"
    "  // get table ptr\n"
    "  tableNm find execute to tablePtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // double check we can see the table\n"
    "  //tableNm find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the table sub dic and then the columns sub dic\n"
    "  tableNm pushTableSub  assert\n"
    "  pushColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicPath.dump\n"
    "\n"
    "  // iterate contents of columns dictionary \n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    tablePtr                     ( value wordNm ^table )\n"
    "    table.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //tablePtr table.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popColumns\n"
    "\n"
    "  popTableSub\n"
    "\n"
    "  // push the partition sub dic and then the columns sub dic\n"
    "  tableNm pushPartitionSub assert\n"
    "\n"
    "  pushPartitionColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicPath.dump\n"
    "\n"
    "  // iterate contents of columns dictionary\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "  object@ execute              ( value )\n"
    "  object@ word.name            ( value wordNm )\n"
    "  tablePtr                     ( value wordNm ^table )\n"
    "  table.slots slots.createColumnVec\n"
    "  object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popPartitionColumns\n"
    "\n"
    "  popPartitionSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT column.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of common.sen
