  // munge of connectorActor.sen
  sDefinition =
    "\""
    "\\\"munged connectorActor.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* connectorActorsen -- connector actor                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"connectorActor.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define the con actor (con.task, con.queue, con.taskset, con.thread)        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "job: con\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* start the connector task                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": connectorStart\n"
    "\n"
    "tp: connectorStart\n"
    "\n"
    "  0 \\\"con.loop\\\" nullPtr \\\"connectorTask\\\" spawnActorTask\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* connector loop                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": con.loop\n"
    "\n"
    "  connectorTaskPrint if \\\"Connector running...\\\" . then\n"
    "\n"
    "  grid.nodes 0 do\n"
    "\n"
    "    I grid.thisNode@ == if\n"
    "\n"
    "      nullptr I senderQueues !\n"
    "      nullptr I senderTasks  !\n"
    "\n"
    "    else\n"
    "\n"
    "      I grid.node     ( ^node )\n"
    "      dup             ( ^node ^node )\n"
    "      node.port swap  ( port ^node )\n"
    "      node.IP         ( port IP )\n"
    "\n"
    "      socket.open  socket.connect\n"
    "\n"
    "      args.verbose if\n"
    "        \\\"Node\\\" grid.thisNode@ >str str.cat\n"
    "        \\\" connected to node\\\" str.cat\n"
    "        I >str str.cat\n"
    "        .\n"
    "      then\n"
    "\n"
    "      // start sender\n"
    "      //\\\"starting sender\\\" .\n"
    "\n"
    "ddlLock::grabWrite\n"
    "\n"
    "     // set up the seed\n"
    "      1 \\\"snd.loop\\\" ( socket 1 \\\"snd.loop\\\" )\n"
    "\n"
    "      // create the actor\n"
    "      \\\"sr\\\" I >str str.cat :job ( socket 1 \\\"snd.loop\\\" \\\"srI\\\" )\n"
    "\n"
    "      // record the senderQueue\n"
    "      dup job.queue I senderQueues ! ( socket 1 \\\"snd.loop\\\" \\\"srI\\\" )\n"
    "      dup job.task  I senderTasks  ! ( socket 1 \\\"snd.loop\\\" \\\"srI\\\" )\n"
    "\n"
    "      // spawn the actors os thread\n"
    "      job.spawn\n"
    "\n"
    "ddlLock::dropWrite\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  // set grid as started\n"
    "  true grid.started!\n"
    "  grid.thisNodeName@ \\\"Node %v : SE cluster started\\\" str.format .\n"
    "\n"
    "  //1000000 thread.sleep_s\n"
    "\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT connectorActor.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of connectorDrone.sen
