    "\n"
    "    swap  ( <<result>> sender )\n"
    "    to sender  ( <<result>> )\n"
    "\n"
    "    // have receiver pass indirect result onto participant proxy\n"
    "    addPassBackToPP ( << <<result>> <<passBackToPP>> >> )\n"
    "\n"
    "    sender                                                        //! NOT RIGHT\n"
    "    >sendQueue                                         //! MAYBE RIGHT NOW -alka\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT coordinatorProxy.sen"_Stz
  ;

