    "\n"
    "    // get dictionary[I]\n"
    "    I pathPick  ( dic )\n"
    "\n"
    "    // push dictionary name\n"
    "    dic.name ( ... dicNm )\n"
    "\n"
    "  loop\n"
    "\n"
    "  // push number of dictionary names\n"
    "  pathDepth ( ... #dics )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set dictionary path                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathSet ( ... \\\"<subFolder>\\\" nFolders -- )\n"
    "\n"
    "  //dicPath.set\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words in the current dictionary                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": words\n"
    "\n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ word.name .          // print the name of the word\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words (long form) in the current dictionary                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": symbols\n"
    "\n"
    "  0 pathPick dic.lastWord\n"
    "  begin dup while\n"
    "    dup word.name .put \\\" \\\" .put dup word.kind@ word.name .put .\\\\n\n"
    "    word.prev\n"
    "  repeat\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get all words in the current dictionary as a single string                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listContents\n"
    "\n"
    "  0 locals| count |\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR)\\\" metadata!\n"
    "    \\\"\\\"                              // initial contents string\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "    1 count + to count\n"
    "    \\\"row: ('\\\" str.cat\n"
    "    object@ word.name str.cat       // add name of the word to contents string\n"
    "    // add word kind to ls string\n"
    "    \\\"')\\\\n\\\" str.cat                     //\n"
    "    object@ word.prev object!       // step backwards thru words\n"
    "    next                            //\n"
    "    count task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"\\\"                              // initial contents string\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "      object@ word.name str.cat     // add name of the word to contents string\n"
    "      // add word kind to ls string\n"
    "      \\\" \\\" str.cat                   //\n"
    "      object@ word.prev object!     // step backwards thru words\n"
    "    next                            //\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get all words in the current dictionary as a single string (indexes)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexesContents ( -- )\n"
    "\n"
    "  0 0 locals| iCount pIndexPtr |\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, isUnique BOOLEAN, isPrimaryKey BOOLEAN)\\\" metadata!\n"
    "    \\\"\\\"                              // initial contents string\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "\n"
    "      // get the index ptr\n"
    "      object@ word.name findInCurrent execute to pIndexPtr\n"
    "\n"
    "      // skip hidden index\n"
    "      pIndexPtr index.isHidden@ not if\n"
    "\n"
    "        // increment count\n"
    "        1 iCount + to iCount\n"
    "\n"
    "        // index a primary key ?\n"
    "        pIndexPtr index.isPrimaryKey@\n"
    "        if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "        // index is unique ?\n"
    "        pIndexPtr index.isUnique@\n"
    "        if \\\"true\\\" else \\\"false\\\" then\n"
    "\n"
    "        // add word kind to ls string\n"
    "        object@ word.name\n"
    "\n"
    "        \\\"row: ('%v',%v,%v)\\\\n\\\" str.format\n"
    "        str.cat\n"
    "      then\n"
    "      object@ word.prev object!       // step backwards thru words\n"
    "    next\n"
    "    iCount task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "    \\\"\\\"                              // initial contents string\n"
    "\n"
    "    0 pathPick dic.wordCount locals| iCountIndexes |\n"
    "    0 pathPick dic.lastWord dup\n"
    "    iterate                         // setup iteration of words\n"
    "\n"
    "      // get the index ptr\n"
    "      object@ word.name findInCurrent execute to pIndexPtr\n"
    "\n"
    "        // increment count\n"
    "        1 iCount + to iCount\n"
    "\n"
    "        // skip hidden index\n"
    "        pIndexPtr index.isHidden@ not if\n"
    "\n"
    "          object@ word.name               // add name of the word to contents string\n"
    "          str.cat\n"
    "\n"
    "          // index is unique ?\n"
    "          pIndexPtr index.isUnique@\n"
    "          if \\\" unique\\\" str.cat then\n"
    "\n"
    "          // index a primary key ?\n"
    "          pIndexPtr index.isPrimaryKey@\n"
    "          if \\\" primary\\\" str.cat then\n"
    "\n"
    "          iCount iCountIndexes 1 - == not if \\\" , \\\" str.cat then\n"
    "\n"
    "        then\n"
    "\n"
    "        object@ word.prev object!         // step backwards thru words\n"
    "      next\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget all words in given dictionary                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": forgetAll ( dic -- )\n"
    "\n"
    "  dup dic.lastWord not if drop exit then\n"
    "\n"
    "  dup pathPush\n"
    "\n"
    "  begin\n"
    "\n"
    "    dup dic.lastWord word.name :forget\n"
    "\n"
    "    dup dic.lastWord not until\n"
    "\n"
    "  pathDrop\n"
    "\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a subdictionary under given dic                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :folder ( \\\"<subDicNm>\\\" dic -- )\n"
    "\n"
    "  pathPush :dic tick folder swap execute dic.kind! pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* clear task dictionary stack                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicPath.clear\n"
    "\n"
    "  pathDepth 0 ?do\n"
    "    pathDrop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop all dictionaries from given stack                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicPath.dropAll ( dicStack -- )\n"
    "\n"
    "  locals| dicStack |\n"
    "\n"
    "  dicStack dicPath.depth 0 ?do\n"
    "    dicStack dicPath.drop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set task dictionary stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dicPath.set ( ... #dics -- )\n"
    "\n"
    "  // this word puts the folder path on the stack into task dictionary stack\n"
    "  // ( ... \\\"<subFolderC>\\\"  \\\"<subFolderB>\\\"  \\\"<subFolderA>\\\" \\\"main\\\" 4 )\n"
    "\n"
    "  tp: dicPath.set\n"
    "\n"
    "  dicPath.clear\n"
    "\n"
    "  0 do\n"
    "\n"
    "    dup \\\"<main>\\\" str.equal if\n"
    "      drop\n"
    "      dic.main\n"
    "      pathPush\n"
    "    else\n"
    "\n"
    "      dup \\\"seitf\\\" str.equal if\n"
    "        drop\n"
    "      else\n"
    "\n"
    "        find\n"
    "        execute\n"
    "        pathPush\n"
    "      then\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop top dictionary from path                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pathDropAll ( -- )\n"
    "\n"
    "  // push the dic stack of this task\n"
    "  task::this task.dicStack\n"
    "\n"
    "  // drop the top dictionary\n"
    "  dicPath.dropAll\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT dicPath.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of dir.sen
  sDefinition =
    "\""
    "\\\"munged dir.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* dir.sen -- directory related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"dir.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dir is use as a kind of word to identify directories                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dir ;\n"
    "\n"
    ": isDir word.kind@ tick dir eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dir using name from input stream                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dir:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dir allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIR word.this >body object.class!\n"
    "  tick dir word.this word.kind!\n"
    "  word.this >body dir.init\n"
    "  true word.this >body object.wordbody!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a dir using name on stack                    (leaves file on stack) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :dir\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_dir allot\n"
    "  word.this >body object.magic!\n"
    "  CN_DIR word.this >body object.class!\n"
    "  tick dir word.this word.kind!\n"
    "  word.this >body dir.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "\n"
    ": dirtest\n"
    "\n"
    "//traceon\n"
    "\n"
    "  \\\"__dir\\\" :dir execute >r\n"
    "\n"
    "  \\\"/tmp\\\" r0 dir.path!\n"
    "\n"
    "  r0 dir.open if \\\"opened\\\" . else \\\"not opened\\\" . rdrop exit then\n"
    "\n"
    "  begin\n"
    "    r0 dir.read\n"
    "    while\n"
    "      r0 dir.entryName .\n"
    "  repeat\n"
    "\n"
    "  r0 dir.close\n"
    "\n"
    "  rdrop\n"
    "\n"
    "  \\\"__dir\\\" find word.forget\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT dir.sen"_Stz
  ;

