  // munge of distExporter.sen
  sDefinition =
    "\""
    "\\\"munged distExporter.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* distExporter.sen -- distributed table exporter                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"distExporter.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distributed export                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": distExport ( \\\"<fileNm>\\\" ^table )\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distributed export                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": distTableExporter ( \\\"<fileNm>\\\" \\\"<tableNm>\\\" )\n"
    "\n"
    "  0 locals| dexPlan |\n"
    "\n"
    "  // push schema name\n"
    "  2 pathPick dic.name  ( \\\"<fileNm>\\\" \\\"<tableNm>\\\" \\\"<schemaNm>\\\" )\n"
    "\n"
    "  // push catalog name\n"
    "  4 pathPick dic.name  ( \\\"<fileNm>\\\" \\\"<tableNm>\\\" \\\"<schemaNm>\\\" \\\"<catalogNm>\\\" )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // prepare plan\n"
    "  4  // 5 values to revers\n"
    "  reverse  ( \\\"<catalogNm>\\\" \\\"<schemaNm>\\\" \\\"<tableNm>\\\" \\\"<fileNm>\\\" )\n"
    "  dexPlanner to dexPlan\n"
    "\n"
    "  //swap dexPlanner to dexPlan\n"
    "\n"
    "  // set this task as the executing task in the plan\n"
    "  task::this dexPlan plan.executingTask!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute (and compile) the plan\n"
    "  dexPlan distributePlan\n"
    "\n"
    "  // this task to wait for 1 ack\n"
    "  1 setAcks\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // execute the plan\n"
    "  dexPlan executePlan\n"
    "\n"
    "  //\\\"PlanTest waiting for ack\\\" .\n"
    "\n"
    "  // this task waits till ack'd by the responseOp\n"
    "  ackWait\n"
    "\n"
    "  //\\\"PlanTest got ack\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // reap the plan\n"
    "  //dexPlan reapPlan\n"
    "\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT distExporter.sen"_Stz
  ;

