  // munge of gridActors.sen
  sDefinition =
    "\""
    "\\\"munged gridActors.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* gridActors -- grid actors                                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"gridActors\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn the grid actors C, PP, CP and P                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnGridActors\n"
    "\n"
    "  /*\n"
    "\n"
    "    r->C->PP->P<-CP\n"
    "       |\n"
    "       +->PP-> (snd ... rcv) ->CP->P\n"
    "       |\n"
    "       +->PP-> (snd ... rcv) ->CP->P\n"
    "\n"
    "  */\n"
    "\n"
    "  grid.nodes 0 do\n"
    "\n"
    "    //\n"
    "    // participant for node I\n"
    "    //\n"
    "\n"
    "    0 \\\"pLoop\\\"\n"
    "\n"
    "    \\\"p\\\" I >str str.cat :createWorkerActor\n"
    "    dup findActorQueue I pQueues !\n"
    "    dup findActorTask  I pTasks  !\n"
    "    spawnWorkerActor\n"
    "\n"
    "    //\n"
    "    // coordinator proxy for node I\n"
    "    //\n"
    "\n"
    "    I I pTasks @ 2 \\\"cpLoop\\\"\n"
    "    \\\"cp\\\" I >str str.cat :createWorkerActor\n"
    "    dup findActorQueue I cpQueues !\n"
    "    dup findActorTask  I cpTasks  !\n"
    "    spawnWorkerActor\n"
    "\n"
    "    //\n"
    "    // partitipant proxy for node I\n"
    "    //\n"
    "\n"
    "    I grid.thisNode@ == if\n"
    "      I I pTasks  @ 2 \\\"ppLoop\\\"\n"
    "    else\n"
    "      I I cpTasks @ 2 \\\"ppLoop\\\"\n"
    "    then\n"
    "\n"
    "    \\\"pp\\\" I >str str.cat :createWorkerActor\n"
    "    dup findActorQueue I ppQueues !\n"
    "    dup findActorTask  I ppTasks  !\n"
    "    spawnWorkerActor\n"
    "\n"
    "  loop\n"
    "\n"
    "  //\n"
    "  // coordinator for this node\n"
    "  //\n"
    "  0 \\\"cLoop\\\"\n"
    "  \\\"c\\\" :createWorkerActor  ( 0 \\\"cLoop\\\" \\\"c\\\" )\n"
    "\n"
    "  spawnWorkerActor\n"
    "\n"
    "  args.verbose if\n"
    "    cpQueuesDump\n"
    "  then\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "spawnGridActors\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* queue an indirect call set to the coordinator and wait for indirect result */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >coordinator> ( <<call*>> -- <<result>> )\n"
    "\n"
    "tp: >coordinator>\n"
    "\n"
    "/*\n"
    "  // could be task such as req.task or ld#.task\n"
    "\n"
    "  addSetCaller ( << <<call*>> <<caller>> >> )\n"
    "*/\n"
    "\n"
    "  // target actor is coordinator\n"
    "  c.task >jobQueue;a> ( <<result>> )\n"
    "\n"
    "tp: resumedbyCoord\n"
    "\n"
    "  // we expect an indirect result\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get coordinator to send indirect call to participant on a node to execute  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>oneParticipant> ( <<call>> nodeNo -- bool )\n"
    "\n"
    "  // a) we are in loader sub task\n"
    "  // b) indirect call on stack is to be executed by participant on given nodeNo\n"
    "\n"
    "  tp: >>oneParticipant>\n"
    "\n"
    "  // check if grid has been started if number of nodes > 1\n"
    "  grid.nodes 1 > if\n"
    "    grid.started@ true != if\n"
    "      \\\"GRID NOT STARTED ...\\\" . false\n"
    "    then\n"
    "  then\n"
    "\n"
    "  // assert we are in loader subtask\n"
    "  2 task::this task.name@ str.left \\\"sl\\\" str.equal assert\n"
    "\n"
    "  // save the node number\n"
    "  >r\n"
    "\n"
    "  // add call to setDicPath to be same as this req.task (run by participant)\n"
    "  addSetDicPath ( <<call>> )\n"
    "\n"
    "  // add indirect call to participant on given node\n"
    "  r> addSendParticipant ( <<call>> )\n"
    "\n"
    "  // add call to setCaller (to be run by coordinator)\n"
    "  addSetCaller ( <<call>> )\n"
    "\n"
    "  // queue on coordinator (which waits for a indirect result)\n"
    "  >coordinator> ( bool )\n"
    "\n"
    "  valset>\n"
    "\n"
    "  // drop number of values\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get coordinator to send indirect call to all participant to execute        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>allParticipants> ( <<$$>> -- bool )\n"
    "\n"
    "  // a) we are in request task (req.task)\n"
    "  // b) indirect call on stack is to be executed by all participants\n"
    "\n"
    "tp: >>allParticipants>\n"
    "\n"
    "   // check if grid has been started if number of nodes > 1\n"
    "   grid.nodes 1 > if\n"
    "     grid.started@ true != if\n"
    "       drop ( ) // drop the valsetr\n"
    "       EC_CLUSTER_NOT_STARTED <FAILURE_RESULT> 1 false exit\n"
    "     then\n"
    "  then\n"
    "\n"
    "  task::this task.name@ \\\"req.task\\\" str.equal assert\n"
    "\n"
    "  // add call to setDicPath to be same as this req.task (run by participant)\n"
    "  addSetDicPath ( <<call>> )\n"
    "\n"
    "  // add indirect call to participants\n"
    "  addSendParticipants ( <<call>> )\n"
    "\n"
    "  // add call to setCaller (to be run by coordinator)\n"
    "  addSetCaller ( <<call>> )\n"
    "\n"
    "  // queue on coordinator (which waits for a indirect result)\n"
    "  >coordinator> ( bool )\n"
    "\n"
    "  valset>\n"
    "\n"
    "  // drop number of values\n"
    "  drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dispatch indirect call to given participant (for use in coordinator)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dispatch ( ... #values actorNo -- ..result.. )\n"
    "\n"
    "  addSetCaller ( << <<call*>> <<caller>> >> )\n"
    "\n"
    "  // determine which queue to forward to\n"
    "  dup ( ... #values actorNo actorNo )\n"
    "  grid.thisNode@ ( ... #values actorNo actorNo grid.thisNode@ )\n"
    "  == ( ... #values actorNo true|false )\n"
    "  if ( ... #values actorNo )\n"
    "\n"
    "    // actor will be the participant for this node\n"
    "    pTasks @ ( ... #values pTask )\n"
    "\n"
    "  else\n"
    "\n"
    "    // actor will be participant proxy for other node\n"
    "    ppTasks @ ( ... #values ppTask )\n"
    "\n"
    "  then\n"
    "\n"
    "  // transfer to another actors and wait for result\n"
    "  >jobQueue;a> ( ..result.. )\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT gridActors.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of gridModel.sen
  sDefinition =
    "\""
    "\\\"munged gridModel.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* gridModel.sen -- grid model group                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "int:  queryCount\n"
    "\n"
    "\\\"gridModel.sen\\\" .verbose\n"
    "\n"
    "\\\"node.sen\\\" include\n"
    "\\\"grid.sen\\\" include\n"
    "\\\"nodeCursor.sen\\\" include\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT gridModel.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of index.sen
  sDefinition =
    "\""
    "\\\"munged index.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* index.sen -- index related words                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"index.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* index is used as a kind of word to identify indexes                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an indexes folder under given named table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndexes ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING INDEXES FOR TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"indexes\\\"     ( dic \\\"indexes\\\" )\n"
    "  swap         ( \\\"indexes\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    ": isIndex word.kind@ tick index eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name from input stream (doesnt leave index on stk)   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_index allot\n"
    "  word.this >body object.magic!\n"
    "  CN_INDEX word.this >body object.class!\n"
    "  word.this >body index.init\n"
    "  true word.this >body object.wordbody!\n"
    "  tick index word.this word.kind!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name on the stack (leaves index on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :index\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_index allot\n"
    "  word.this >body object.magic!\n"
    "  CN_INDEX word.this >body object.class!\n"
    "  word.this >body index.init\n"
    "  true word.this >body object.wordbody!\n"
    "  tick index word.this word.kind!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within indexes folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinIndexes\n"
    "  0 pathPick dic.name \\\"indexes\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInIndexes\n"
    "  withinIndexes if true exit then\n"
    "  EC_NOT_IN_INDEXES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is indexes                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInIndexes ( -- t|f )\n"
    "  withinIndexes assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is an index                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsIndex ( \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  0 locals| indexPtr indexNm |\n"
    "\n"
    "  indexNm find ( indexPtr )\n"
    "  to indexPtr\n"
    "\n"
    "  indexPtr\n"
    "  not ( indexPtr bool )\n"
    "\n"
    "  if\n"
    "    EC_NO_SUCH_INDEX false ( errorCode false )\n"
    "  exit\n"
    "  then\n"
    "\n"
    "  indexPtr ( indexPtr )\n"
    "  word.kind@ ( ^word )\n"
    "  tick index ( ^word ^word )\n"
    "  eql ( bool )\n"
    "  if\n"
    "    //indexPtr execute index.isHidden@ if\n"
    "    //  EC_NO_SUCH_INDEX false ( errorCode false )\n"
    "    //  exit\n"
    "    //then\n"
    "\n"
    "    true ( true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "\n"
    "  EC_NOT_AN_INDEX false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotIndex ( \\\"<word>\\\" )\n"
    "\n"
    "  findInCurrent not if true exit then\n"
    "  EC_INDEX_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the index sub folder and push it onto task dictionary                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexSub ( \\\"<indexNm>\\\" -- )\n"
    "  dup checkIsIndex not if EC_NO_SUCH_INDEX false exit then\n"
    "  find execute index.subDic pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the index sub folder                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexSub\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the indexes folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexes ( -- )\n"
    "  \\\"indexes\\\" find execute pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the indexes folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexes\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable index                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeIndex ( \\\"<indexNm>\\\" \\\"<tableNm>\\\" --  true | errorCode false )\n"
    "\n"
    "  locals| tableNm indexNm |\n"
    "\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  tableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  tableNm pushTable assert\n"
    "\n"
    "  tableNm find execute table.indexCount\n"
    "  C_INDEXES_PER_TABLE == if EC_MAX_INDEXES popTable assertInTables false exit then\n"
    "\n"
    "  pushIndexes assert\n"
    "\n"
    "  indexNm checkIsNotIndex not if popIndexes popTable assertInTables false exit then\n"
    "\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable index folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveIndex ( \\\"<indexNm>\\\" \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  locals| tableNm indexNm |\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables       not if false exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  tableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  true ( \\\"<indexNm>\\\" true )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* tidy up of the index                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": indexTidyUp ( \\\"<indexNm>\\\" -- )\n"
    "\n"
    "   find execute ( ^indexPtr )\n"
    "\n"
    "   // truncate the index\n"
    "   dup index.truncate\n"
    "   \n"
    "   // forget all column names\n"
    "   dup index.subDic\n"
    "   pathPush\n"
    "   \\\"columns\\\" find execute forgetAll\n"
    "   pathDrop\n"
    "\n"
    "  // forget the sub dictionary\n"
    "   index.subDic forgetAll\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyze an index of a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex allParticipants 2 returnResult ( detailed \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: analyzeIndex\n"
    "\n"
    "  find execute\n"
    "  index.analyze\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get index pointer and put into task.seitf.currentIndex                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": getIndex ( \\\"<indexNm>\\\" \\\"<tableNm>\\\" -- <R> )\n"
    "\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  assertInTables\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // get index ptr\n"
    "  sIndexNm findInCurrent execute\n"
    "\n"
    "  task::this task.seitf@ seitf.index!\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* clear task.seitf.currentIndex                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": returnIndex ( )\n"
    "\n"
    "  nullptr task::this task.seitf@ seitf.index!\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make_index (invoked from makeIndex)                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": make_index ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  0 0 locals| indexPtr tablePtr indexNm tableNm |\n"
    "\n"
    "  pushIndexes assert\n"
    "\n"
    "  // create the index\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "  :index ( ^index )\n"
    "\n"
    "  // drop the index word\n"
    "  drop (  )\n"
    "\n"
    "  // make index columns\n"
    "  indexNm \\\"makeIndexColumns\\\" find execute\n"
    "\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "\n"
    "  // find the index\n"
    "  find execute ( ^index )\n"
    "  to indexPtr\n"
    "\n"
    "  // find the table\n"
    "  tableNm find execute\n"
    "  to tablePtr\n"
    "\n"
    "  // push the table and index\n"
    "  tablePtr indexPtr ( ^index ^table )\n"
    "\n"
    "  // set the table in the index\n"
    "  index.table! (  )\n"
    "\n"
    "  // add the index in the table\n"
    "  indexPtr tablePtr table.addIndex\n"
    "\n"
    "  popIndexes\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index (run by participant)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndex allParticipants 2 checkResult ( \\\"<tableNm>\\\" \\\"<indexNm>\\\"  -- true n# true )\n"
    "\n"
    "tp: makingIndex\n"
    "\n"
    "  locals| indexNm tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  \\\"MAKING INDEX \\\" indexNm str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm\n"
    "  pushTable assert\n"
    "\n"
    "  tableNm indexNm make_index\n"
    "\n"
    "  popTable\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by keySelectIndex request)    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": exactSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf iPartitionNo -- )\n"
    "\n"
    "  0 0 0 0 locals| entry pTempEntryBuffer pEntryBuffer pIndex iPartitionNo pSeitf upper lower key |\n"
    "\n"
    "  tp: keySelectIdx\n"
    "\n"
    "  //\\\"fetchTask started\\\" .\n"
    "  \n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempEntryBuffer\\\" .\n"
    "  iPartitionNo pIndex entryBuffer::create to pTempEntryBuffer\n"
    "\n"
    "  // get the entryBuffer looking for the key\n"
    "  key iPartitionNo pIndex index.buffer ( pEntryBuffer )\n"
    "  to pEntryBuffer\n"
    "\n"
    "  // did we get an index buffer ?\n"
    "  pEntryBuffer if\n"
    "    // position in the index buffer at the key\n"
    "    key pEntryBuffer pIndex index.position\n"
    "    to entry\n"
    "  then\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    pTempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    pTempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    // mark that a fetch task has ended\n"
    "    pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no key match\n"
    "  begin\n"
    "    entry\n"
    "    while\n"
    "\n"
    "    // check if exact key match\n"
    "    key pIndex entry entry.matches if\n"
    "\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      pIndex entry entry.toDataRow pTempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        pTempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        //\\\"Creating a tempEntryBuffer\\\" .\n"
    "        iPartitionNo pIndex entryBuffer::create to pTempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        pIndex entry entry.toDataRow pTempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry pEntryBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current entryBuffer\n"
    "        pEntryBuffer entryBuffer.nextBuffer to pEntryBuffer\n"
    "\n"
    "        pEntryBuffer if\n"
    "          entry pEntryBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry did not match the key, null the entry and break from loop\n"
    "      0  to entry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  pTempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  pTempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "  // mark that a fetch task has ended\n"
    "  pSeitf seitf.fetchTaskEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index (run by participant)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadIndexes allParticipants 0 checkResult ( -- true n# true )\n"
    "\n"
    "tp: loadIndexes\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"LOADING INDEXES on NODE \\\" grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  \\\"indexes\\\"\n"
    "  find execute pathPush\n"
    "\n"
    "  0 pathPick dic.lastWord dup\n"
    "    iterate\n"
    "    object@ word.name\n"
    "    find execute ( ^index )\n"
    "\n"
    "    // populate only non-hidden indexes\n"
    "    dup index.isHidden@ not if\n"
    "      index.populate\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!\n"
    "  next\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lowerSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf partition -- )\n"
    "\n"
    "  0 0 0 0 locals| pIndex entry tempEntryBuffer indexBuffer iPartitionNo pSeitf upper lower key |\n"
    "\n"
    "  tp: lowerSelectIdxTask\n"
    "\n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // get the indexBuffer looking for the lower key\n"
    "  lower iPartitionNo pIndex index.buffer ( indexBuffer )\n"
    "  to indexBuffer\n"
    "\n"
    "  // did we get an index buffer ?\n"
    "  indexBuffer if\n"
    "    // position in the index buffer at the lower key\n"
    "    lower indexBuffer pIndex index.position\n"
    "    to entry\n"
    "  then\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "    \n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    // mark that a fetch task has ended\n"
    "    pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "   // mark that a fetch task has ended\n"
    "   pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "    \n"
    "    // insert row from entry in tempEntryBuffer\n"
    "    //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "    pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "    // check if we managed to insert the entry\n"
    "    not if\n"
    "      // buffer must be full\n"
    "      // put this tempEntryBuffer in seitf bufferQueue\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "      // create another temporary index buffer for the results\n"
    "      //\\\"Creating a tempIndexBuffer\\\" .\n"
    "      iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "      // insert row from entry in temporary buffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "      assert\n"
    "    then\n"
    "\n"
    "    // move to next entry in the buffer\n"
    "    entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "    entry not if\n"
    "      // get next buffer from the current indexBuffer\n"
    "      indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "      indexBuffer if\n"
    "        entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      then\n"
    "    then\n"
    "\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "  // mark that a fetch task has ended\n"
    "  pSeitf seitf.fetchTaskEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rangeSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf iPartitionNo -- )\n"
    "\n"
    "//\\\"rangeSelectIdxTask\\\" .\n"
    "\n"
    "  // save args\n"
    "  locals| iPartitionNo pSeitf sUpper sLower sKey |\n"
    "\n"
    "  // local variables\n"
    "  0 0 0 0 0 locals| pIndex pUpperEntry pIndexEntry pIndexBuffer pResultBuffer |\n"
    "\n"
    "  tp: rangeSelectIdxTask\n"
    "\n"
    "  //debug::trap\n"
    "\n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  // save seitf into this task\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // create a temporary buffer for the results\n"
    "  iPartitionNo pIndex entryBuffer::create to pResultBuffer\n"
    "\n"
    "  // get the indexBuffer looking for the lower key\n"
    "  sLower iPartitionNo pIndex index.buffer to pIndexBuffer\n"
    "\n"
    "  // did we get an index buffer ?\n"
    "  pIndexBuffer if\n"
    "    // position in the index buffer at the lower key\n"
    "    sLower pIndexBuffer pIndex index.position to pIndexEntry\n"
    "  then\n"
    "\n"
    "  // did we find an entry ?\n"
    "  pIndexEntry not if\n"
    "\n"
    "    // mark this result buffer as the last buffer\n"
    "    pResultBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty result buffer\n"
    "    pResultBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    // mark that a fetch task has ended\n"
    "    pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the index buffer till no more index entries\n"
    "  begin\n"
    "  pIndexEntry\n"
    "  while\n"
    "\n"
    "    // check against upper bound\n"
    "    sUpper pIndexEntry iPartitionNo pIndex index.upper if\n"
    "      \n"
    "      // look up data row and insert row into result buffer\n"
    "      pIndex pIndexEntry entry.toDataRow pResultBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this result buffer in seitf buffer queue\n"
    "        pResultBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another result buffer\n"
    "        iPartitionNo pIndex entryBuffer::create to pResultBuffer\n"
    "\n"
    "        // look up data row and insert row into result buffer\n"
    "        pIndex pIndexEntry entry.toDataRow pResultBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next index entry in the index buffer\n"
    "      pIndexEntry pIndexBuffer entryBuffer.nextEntry to pIndexEntry\n"
    "\n"
    "      pIndexEntry not if\n"
    "        // get next index buffer from the current index buffer\n"
    "        pIndexBuffer entryBuffer.nextBuffer to pIndexBuffer\n"
    "\n"
    "        pIndexBuffer if\n"
    "         pIndexEntry pIndexBuffer entryBuffer.nextEntry to pIndexEntry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry beyond upper, null the entry and break from loop\n"
    "      0  to pIndexEntry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  // mark this result buffer as the last buffer\n"
    "  pResultBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the result buffer in the seitf buffer queue\n"
    "  pResultBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "  // mark that a fetch task has ended\n"
    "  pSeitf seitf.fetchTaskEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print rows from entries of an index buffer                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": printRows ( ^pIndex ^pIndexBuffer --  )\n"
    "\n"
    "  0 0 locals| nRowCount pEntry pIndexBuffer pIndex iPartitionNo |\n"
    "\n"
    "  // get the partitionNo\n"
    "  pIndexBuffer entryBuffer.partition@ to iPartitionNo\n"
    "\n"
    "  // get the entry\n"
    "  pIndexBuffer entryBuffer.firstEntry to pEntry\n"
    "\n"
    "  begin\n"
    "    pEntry\n"
    "    while\n"
    "\n"
    "      display@ if\n"
    "        args.metadata if\n"
    "          pIndex pEntry entry.embeddedRow\n"
    "          iPartitionNo grid::toPartition\n"
    "          \\\"row: (%v,%v)\\\\n\\\" str.format .put\n"
    "        else\n"
    "          pIndex pEntry entry.embeddedRow \\\"row: (%v)\\\\n\\\" str.format .put\n"
    "        then\n"
    "      then\n"
    "      1 nRowCount + to nRowCount\n"
    "      pEntry pIndexBuffer entryBuffer.nextEntry to pEntry\n"
    "\n"
    "    repeat\n"
    "\n"
    "    // return nRowCount\n"
    "    nRowCount\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop buffer off the buffer queue                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popBuffer ( ^pBufferQueue --  )\n"
    "\n"
    "  locals| pBufferQueue |\n"
    "\n"
    "  begin\n"
    "    pBufferQueue queue.pop ( value true | false )\n"
    "\n"
    "    // try again if no value\n"
    "    not while\n"
    "      //REQUST_LOOP2\n"
    "      //task.yield\n"
    "      args.sleep thread.sleep_ms\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* populate the index with data                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": populateIndex allParticipants 1 returnFinalResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "tp: populateIndex\n"
    "\n"
    "  0 locals| pIndex sIndexNm |\n"
    "\n"
    "  // get index ptr\n"
    "  sIndexNm findInCurrent execute to pIndex\n"
    "\n"
    "  pIndex index.populate\n"
    "\n"
    "  if\n"
    "    true <SUCCESS_RESULT>\n"
    "  else\n"
    "    // return final result returns error code\n"
    "    EC_DUPLICATE_KEY <FAILURE_RESULT>\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows from buffers from teh buffer queue of the seitf                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchQueueBufferRows ( -- )\n"
    "\n"
    "  0 0 0 0 0 locals| nLastBuffers nRowCount pIndex pIndexBuffer pSeitf |\n"
    "\n"
    "  // get the seitf of the task\n"
    "  task::this task.seitf@ to pSeitf\n"
    "\n"
    "  // get index\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // get number of last buffers\n"
    "  pSeitf seitf.lastbuffers@ to nLastBuffers\n"
    "\n"
    "  // loop thru buffers\n"
    "  true\n"
    "  begin\n"
    "  while\n"
    "\n"
    "    // pop a buffer off the seitf buffer queue\n"
    "    pSeitf seitf.bufferQueue@ popBuffer to pIndexBuffer\n"
    "\n"
    "    // print the rows from the index buffer\n"
    "    pIndex pIndexBuffer printRows nRowCount + to nRowCount\n"
    "\n"
    "    // check if last buffer\n"
    "    pIndexBuffer entryBuffer.isLast@ if\n"
    "\n"
    "      nLastBuffers 1 - to nLastBuffers\n"
    "      0 nLastBuffers == if\n"
    "        false\n"
    "      else\n"
    "        true\n"
    "      then\n"
    "    else\n"
    "      true  // no more entries, move to next buffer\n"
    "    then\n"
    "\n"
    "    pIndexBuffer entryBuffer.delete\n"
    "    //\\\"Deleted buffer\\\" .\n"
    "\n"
    "  repeat\n"
    "\n"
    "  // delete the buffer queue from the seitf\n"
    "  pSeitf seitf.bufferQueue@ queue.delete\n"
    "  0 pSeitf seitf.bufferQueue!\n"
    "\n"
    "  args.metadata if\n"
    "    nRowCount pSeitf seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  nRowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf iPartitionNo -- )\n"
    "\n"
    "  0 0 0 0 locals| pIndex entry tempEntryBuffer indexBuffer iPartitionNo pSeitf upper lower key |\n"
    "\n"
    "  tp: scanSelectIdxTask\n"
    "\n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // position in the first index buffer\n"
    "  iPartitionNo pIndex index.positionFirst\n"
    "  to indexBuffer\n"
    "\n"
    "  // get the first entry in the buffer\n"
    "  indexBuffer entryBuffer.firstEntry\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending last tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    // mark that a fetch task has ended\n"
    "    pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        //\\\"Creating a tempIndexBuffer\\\" .\n"
    "        iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      else\n"
    "        // there is an entry\n"
    "        // check if seitf exiting\n"
    "        pSeitf seitf.isExiting if\n"
    "          0 to entry\n"
    "        then\n"
    "      then\n"
    "    repeat\n"
    "\n"
    "  // mark this buffer as the last buffer\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "  // mark that a fetch task has ended\n"
    "  pSeitf seitf.fetchTaskEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set isUnique property of index                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setIndexIsUnique allParticipants 2 checkResult ( \\\"<indexNm>\\\" true/false -- )\n"
    "\n"
    "  assert::stack_2\n"
    "\n"
    "  locals| sIndexNm bIsUnique |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  bIsUnique ( bIsUnique )\n"
    "\n"
    "  sIndexNm find execute ( bIsUnique index^ )\n"
    "\n"
    "  index.isUnique! ( )\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get size of index                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex ( \\\"<indexNm>\\\" -- \\\"<size>\\\" )\n"
    "\n"
    "  find execute ( index^ )\n"
    "\n"
    "  index.space 0 swap number.magnitude >str\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* select using index (called by fetchRowsIndex_req)                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnSelectTask ( \\\"<sExactKey>\\\" \\\"<sLowerKey>\\\" \\\"<sUpperKey>\\\"\n"
    "\\\"<sSelectTaskSeed>\\\" \\\"<sIndexNm>\\\" pBufferQueue <bSinglePartition> --  )\n"
    "\n"
    "tp: selectIndex\n"
    "\n"
    "  //debug::trap\n"
    "\n"
    "  // task is a request server\n"
    "  task::this task.kind@ TK_REQUEST_SERVER == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //   and the seitf will have an index\n"
    "  //   and the seitf will have a bufferQueue\n"
    "  //\n"
    "  //assert::stack_5\n"
    "\n"
    "  // save args\n"
    "  locals| bSinglePartition pBufferQueue sIndexNm sSelectTaskSeed sUpperKey sLowerKey sExactKey |\n"
    "\n"
    "  // local variables\n"
    "  0 0 0 0 0 0 0 locals| pIndex iSlots pSeitf pSelectTask nRowCount pIndexBuffer pEntry |\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  task::this task.seitf@ to pSeitf\n"
    "\n"
    "  // push into indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index and put it in the seitf\n"
    "  sIndexNm find execute to pIndex\n"
    "  pIndex pSeitf seitf.index!\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // create the buffer queue in the seitf\n"
    "  //\\\"selectTask.queue\\\" queue::new pSeitf seitf.bufferQueue!\n"
    "\n"
    "  // set the queue in the seitf\n"
    "  pBufferQueue pSeitf seitf.bufferQueue!\n"
    "\n"
    "  bSinglePartition if\n"
    "\n"
    "    0 0 locals| iSlot iPartition |\n"
    "    pSeitf seitf.slot@ to iSlot\n"
    "    pSeitf seitf.partition@ to iPartition\n"
    "\n"
    "    //args.metadata not if\n"
    "    //  iPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    //then\n"
    "\n"
    "    // create a selectTask to execute the key select on the index for the partition\n"
    "    sExactKey sLowerKey sUpperKey pSeitf iSlot 5\n"
    "    sSelectTaskSeed nullptr \\\"selectTask\\\" TK_SELECT_PART spawnServerTask\n"
    "    to pSelectTask\n"
    "\n"
    "  else\n"
    "    // for each slot\n"
    "    grid.slots to iSlots\n"
    "    iSlots 0\n"
    "    do\n"
    "\n"
    "      //args.metadata not if\n"
    "      //  I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "      //then\n"
    "\n"
    "      // create a selectTask to execute the key select on the index for the partition\n"
    "      sExactKey sLowerKey sUpperKey pSeitf I 5\n"
    "      sSelectTaskSeed nullptr \\\"selectTask\\\" TK_SELECT_PART spawnServerTask\n"
    "      to pSelectTask\n"
    "\n"
    "    loop\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove an index                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeIndex allParticipants 1 checkResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: removeIndex\n"
    "  locals| indexNm |\n"
    "\n"
    "  // forward reference :-(\n"
    "  indexNm \\\"indexTidyUp\\\" find execute\n"
    "\n"
    "  indexNm :forget\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": upperSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf partition -- )\n"
    "\n"
    "  0 0 0 0 0 locals| pIndex upperEntry entry tempEntryBuffer indexBuffer iPartitionNo pSeitf upper lower key |\n"
    "\n"
    "  tp: upperSelectIdxTask\n"
    "\n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // position in the first index buffer\n"
    "  iPartitionNo pIndex index.positionFirst\n"
    "  to indexBuffer\n"
    "\n"
    "  // get the first entry in the buffer\n"
    "  indexBuffer entryBuffer.firstEntry\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    // mark that a fetch task has ended\n"
    "    pSeitf seitf.fetchTaskEnded\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "\n"
    "    // check against upper entry\n"
    "    //upperEntry entry entry.same not if\n"
    "    upper entry iPartitionNo pIndex index.upper if\n"
    "      \n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        //\\\"Creating a tempIndexBuffer\\\" .\n"
    "        iPartitionNo pIndex entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        pIndex entry entry.toDataRow tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry beyond upper, null the entry and break from loop\n"
    "      0  to entry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "  // mark that a fetch task has ended\n"
    "  pSeitf seitf.fetchTaskEnded\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify an index of a table                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyIndex allParticipants 1 returnResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: verifyIndex\n"
    "\n"
    "  find execute\n"
    "  index.verify\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows from buffers from teh buffer queue of the seitf                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": groupByQueueBufferRows ( -- )\n"
    "\n"
    "  0 0 0 0 0 0 0 locals| iSlots nRowCount pIndex pIndexBuffer pSeitf pGroupBy pPartialGroupBy |\n"
    "\n"
    "  // get the seitf of the task\n"
    "  task::this task.seitf@ to pSeitf\n"
    "\n"
    "  // get index\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  groupBy::new locals| pGroupBy |\n"
    "  pGroupBy groupBy.start\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  // get slots\n"
    "  grid.slots to iSlots\n"
    "\n"
    "  1\n"
    "  begin\n"
    "  while\n"
    "\n"
    "    // attempt to pop buffer off the tasks buffer queue\n"
    "    pSeitf seitf.bufferQueue@ popBuffer to pIndexBuffer\n"
    "\n"
    "    // print the rows from the index buffer\n"
    "    pIndex pIndexBuffer printRows nRowCount + to nRowCount\n"
    "\n"
    "    // check if last buffer\n"
    "    pIndexBuffer entryBuffer.isLast@ if\n"
    "\n"
    "      //\\\"Reached last buffer\\\" .\n"
    "      iSlots 1 - to iSlots\n"
    "      0 iSlots == if\n"
    "        0\n"
    "      else\n"
    "        1\n"
    "      then\n"
    "    else\n"
    "      1  // no more entries, move to next buffer\n"
    "    then\n"
    "\n"
    "    pIndexBuffer entryBuffer.delete\n"
    "    //\\\"Deleted buffer\\\" .\n"
    "\n"
    "  repeat\n"
    "\n"
    "  // delete the buffer queue from the seitf\n"
    "  pSeitf seitf.bufferQueue@ queue.delete\n"
    "  0 pSeitf seitf.bufferQueue!\n"
    "\n"
    "  args.metadata if\n"
    "    nRowCount pSeitf seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  nRowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "  grid.slots 0\n"
    "  do\n"
    "    I pSeitf seitf.groupBy@ to pPartialGroupBy\n"
    "    pPartialGroupBy pGroupby groupBy.applyPartial\n"
    "    pPartialGroupBy groupBy.delete\n"
    "  loop\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  // delete groupBy\n"
    "  pGroupBy groupBy.end\n"
    "  pGroupBy groupBy.delete\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* select using index (called by fetchRowsIndex_req) -- groupBy               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnGroupByTask ( \\\"<sExactKey>\\\" \\\"<sLowerKey>\\\" \\\"<sUpperKey>\\\"\n"
    "                   \\\"<sSelectTaskSeed>\\\" \\\"<sIndexNm>\\\" --  )\n"
    "\n"
    "  tp: selectIndex\n"
    "\n"
    "  //debug::trap\n"
    "\n"
    "  // task is a request server\n"
    "  task::this task.kind@ TK_REQUEST_SERVER == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //\n"
    "  //assert::stack_5\n"
    "\n"
    "  // save args\n"
    "  locals| sIndexNm sSelectTaskSeed sUpperKey sLowerKey sExactKey |\n"
    "\n"
    "  // local variables\n"
    "  0 0 0 0 0 0 0 locals| iSlots pSeitf pSelectTask nRowCount pIndexBuffer pEntry pIndex |\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  // push into indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index\n"
    "  sIndexNm find execute to pIndex\n"
    "\n"
    "  // find the index andput it in the seitf\n"
    "  task::this task.seitf@ to pSeitf\n"
    "  pIndex pSeitf seitf.index!\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // create the buffer queue in the seitf\n"
    "  \\\"selectTask.queue\\\" queue::new pSeitf seitf.bufferQueue!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // for each slot\n"
    "  grid.slots to iSlots\n"
    "  iSlots 0\n"
    "  do\n"
    "\n"
    "    args.metadata not if\n"
    "      I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    then\n"
    "\n"
    "    // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "    I groupBy::new pSeitf seitf.groupBy!\n"
    "    // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "    // create a selectTask to execute the key select on the index for the partition\n"
    "    sExactKey sLowerKey sUpperKey pSeitf I 5\n"
    "    sSelectTaskSeed nullptr \\\"selectTask\\\" TK_SELECT_PART spawnServerTask\n"
    "    to pSelectTask\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": groupByIdxTask_RH ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" pSeitf iPartitionNo -- )\n"
    "\n"
    "  // save args\n"
    "  locals| iPartitionNo pSeitf sUpper sLower sKey |\n"
    "\n"
    "  // local variables\n"
    "  0 0 0 0 0 locals| pIndex pUpperEntry pIndexEntry pIndexBuffer pResultBuffer |\n"
    "\n"
    "  tp: rangeSelectIdxTask\n"
    "\n"
    "  //debug::trap\n"
    "\n"
    "  // task is a select participant running on server thread\n"
    "  task::this task.kind@ TK_SELECT_PART == assert\n"
    "  task::this task.thread thread.actorModel@ AC_SERVER == assert\n"
    "\n"
    "  // save seitf into this task\n"
    "  pSeitf task::this task.seitf!\n"
    "  pSeitf seitf.index@ to pIndex\n"
    "\n"
    "  // start groupBy operator for this partition\n"
    "  iPartitionNo pSeitf seitf.groupBy@ locals| pGroupBy |\n"
    "  pGroupBy groupBy.start\n"
    "\n"
    "  // create a temporary buffer for the results\n"
    "  iPartitionNo pIndex entryBuffer::create to pResultBuffer\n"
    "\n"
    "  iPartitionNo pIndex index.positionFirst to pIndexBuffer\n"
    "  pIndexBuffer entryBuffer.firstEntry to pIndexEntry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  pIndexEntry not if\n"
    "\n"
    "    // mark this result buffer as the last buffer\n"
    "    pResultBuffer entryBuffer.isLast!\n"
    "\n"
    "    pResultBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  pGroupby pIndexEntry pUpperEntry pIndexBuffer entryBuffer.iterate\n"
    "\n"
    "  // mark this result buffer as the last buffer\n"
    "  pResultBuffer entryBuffer.isLast!\n"
    "  pResultBuffer pSeitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "\""
  " CONSTANT index.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of indexColumn.sen
  sDefinition =
    "\""
    "\\\"munged indexColumn.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* indexColumn.sen -- index column related words                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"indexColumn.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* indexColumn is used as a kind of word to identify index columns            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": indexColumn: ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the index columns sub folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndexColumns ( \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  find execute ( dic )\n"
    "  index.subDic pathPush \\\"columns\\\" :dic drop pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within index columns folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinIndexColumns\n"
    "    0 pathPick dic.name \\\"columns\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes columns folder                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInIndexColumns\n"
    "    withinIndexColumns if true exit then\n"
    "    EC_NOT_IN_COLUMNS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the index column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexColumns ( -- )\n"
    "\n"
    "    \\\"columns\\\" checkIsWord\n"
    "    not if EC_NO_COLUMNS_DIC false exit then\n"
    "    execute pathPush\n"
    "    true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the index column folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexColumns\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create index column as a constant                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :indexColumn ( \\\"<columnName>\\\" )\n"
    "    :constant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check and add an index column                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAddIndexColumn ( \\\"<columnName>\\\" \\\"<indexNm>\\\" \\\"<tableNm>\\\" -- true | eEC false )\n"
    "\n"
    "  locals| tableNm indexNm columnNm |\n"
    "\n"
    "  // check we are in the indexes folder\n"
    "  checkInIndexes not if false exit then\n"
    "\n"
    "  // move out of the indexes folder temporarily\n"
    "  popIndexes\n"
    "\n"
    "  // push the table sub folder\n"
    "  tableNm pushTableSub assert\n"
    "\n"
    "  // push the table columns folder\n"
    "  pushColumns\n"
    "\n"
    "  // look for the index column in the table columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should exist in table\n"
    "  not if EC_INVALID_COLUMN false popColumns popTableSub pushIndexes assert exit then\n"
    "\n"
    "  // pop the columns folder\n"
    "  popColumns\n"
    "\n"
    "  // pop the tables sub folder\n"
    "  popTableSub\n"
    "\n"
    "  // push back the indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // push the index sub folder\n"
    "  indexNm\n"
    "  pushIndexSub assert   // not if false exit then\n"
    "\n"
    "  // push the index columns folder\n"
    "  pushIndexColumns assert // not if false exit then\n"
    "\n"
    "  // look for the column in the indexes columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should not already exist\n"
    "  if EC_DUPLICATE_COLUMN false popIndexColumns popIndexSub exit then\n"
    "\n"
    "  //pop the index columns folder\n"
    "  popIndexColumns\n"
    "\n"
    "  // pop the index sub folder\n"
    "  popIndexSub\n"
    "\n"
    "  assertInIndexes\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of an index                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexColumns ( \\\"<indexNm>\\\" -- list )\n"
    "\n"
    "  find execute ( ^indexPtr )\n"
    "\n"
    "  0 locals| indexCols indexPtr |\n"
    "\n"
    "  indexPtr index.columnCount to indexCols\n"
    "\n"
    "  \\\"\\\"                             // initial ls string\n"
    "  args.metadata if\n"
    "    indexCols 0 do\n"
    "      I indexPtr index.columnType\n"
    "      I indexPtr index.columnName\n"
    "      \\\"row: ('%v', '%v')\\\\n\\\" str.format\n"
    "      str.cat\n"
    "    loop\n"
    "    indexCols task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "\n"
    "    indexCols 0 do\n"
    "      I indexPtr index.columnType\n"
    "      I indexPtr index.columnName\n"
    "      \\\"%v %v \\\" str.format\n"
    "      I 1 + indexCols < if\n"
    "        \\\", \\\" str.cat\n"
    "      then\n"
    "      str.cat\n"
    "    loop\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column (called by addIndexColumn)                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": add_indexColumn ( \\\"<columnNm>\\\" \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  0 locals| indexPtr indexNm columnNm |\n"
    "\n"
    "  // push the index sub folder\n"
    "  indexNm\n"
    "  pushIndexSub assert\n"
    "\n"
    "  // push index columns folder\n"
    "  pushIndexColumns assert\n"
    "\n"
    "  columnNm columnNm    ( \\\"<columnNm>\\\" \\\"<columnNm>\\\" )\n"
    "  :indexColumn\n"
    "\n"
    "  // pop index columns folder\n"
    "  popIndexColumns\n"
    "\n"
    "  // pop the index sub folder\n"
    "  popIndexSub\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column (run by all participants)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addIndexColumn allParticipants 2 checkResult ( \\\"<columnNm>\\\" \\\"<indexNm>\\\" -- <result> )\n"
    "\n"
    "  0 locals| indexPtr indexNm columnNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"ADDING COLUMN \\\" indexNm str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tp: addingIndexColumn\n"
    "\n"
    "  columnNm indexNm add_indexColumn\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the index                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecIndex allParticipants 1 checkResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  0 locals| indexPtr indexNm |\n"
    "\n"
    "  //\\\"columnVecIndex\\\" . indexNm .\n"
    "\n"
    "  // get index ptr\n"
    "  indexNm findInCurrent execute to indexPtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // double check we can see the index\n"
    "  //indexPtr find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the index sub dic and then the columns sub dic\n"
    "  indexNm pushIndexSub assert\n"
    "\n"
    "  pushIndexColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicPath.dump\n"
    "\n"
    "  // iterate contents of columns dictionary \n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    indexPtr                     ( value wordNm ^table )\n"
    "    index.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popIndexColumns\n"
    "\n"
    "  popIndexSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT indexColumn.sen"_Stz
  ;

  vCompileConstant(sDefinition);

