  // munge of partition.sen
  sDefinition =
    "\""
    "\\\"munged partition.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* partition.sen -- partition related words                                   */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"partition.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a partitions folder under given named table                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makePartitions ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  locals| tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    tableNm \\\"MAKING PARTITIONS FOR TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm find execute ( dic )\n"
    "  \\\"partitions\\\" ( dic \\\"partitions\\\" )\n"
    "  swap         ( \\\"partitions\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within partitions folder                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinPartitions\n"
    "  0 pathPick dic.name \\\"partitions\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in partitions folder                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInPartitions\n"
    "  withinPartitions if true exit then\n"
    "  EC_NOT_IN_PARTITIONS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partitions folder and push it onto task dictionary                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushPartitions ( -- )\n"
    "  \\\"partitions\\\" find execute pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partitions folder                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitions\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partition sub folder and push it onto task dictionary             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushPartitionSub ( \\\"<tableNm>\\\" -- )\n"
    "  find execute table.slots slots.subDic pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partition sub folder                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitionSub\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check table can be partitioned                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*\n"
    ": checkPartitionTable ( \\\"<tableNm>\\\" --  true | errorCode false )\n"
    "\n"
    "  locals| sTableNm |\n"
    "tp: checkPartitionTable\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  sTableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  sTableNm pushTable assert\n"
    "  sTableNm find execute table.space\n"
    "  if EC_TABLE_NOT_EMPTY false popTable exit then\n"
    "\n"
    "tp: checkPartitionTable4\n"
    "  popTable\n"
    "\n"
    "  assertInTables\n"
    "tp: checkPartitionTable1\n"
    "  true\n"
    " ;\n"
    "*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is partitions                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInPartitions ( -- t|f )\n"
    "  withinPartitions assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* tidy up of the partition                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": partitionTidyUp ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "   find execute ( ^tablePtr )\n"
    "   \n"
    "   // forget all column names\n"
    "   dup table.slots slots.subDic\n"
    "   pathPush\n"
    "   \\\"columns\\\" find execute forgetAll\n"
    "   pathDrop\n"
    "\n"
    "  // forget the sub dictionary\n"
    "  table.slots slots.subDic forgetAll\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make partition (run by participant)                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": partitionTable allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "tp: partitioningTable\n"
    "\n"
    "  locals| tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  \\\"MAKING PARTITIONS on NODE \\\" grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm ( \\\"<tableNm>\\\" )\n"
    "  find execute pathPush\n"
    "\n"
    "  \\\"partitions\\\" find execute pathPush\n"
    "\n"
    "  // make partition columns\n"
    "  tableNm \\\"makePartitionColumns\\\" find execute\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT partition.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of partitionColumn.sen
  sDefinition =
    "\""
    "\\\"munged partitionColumn.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* partitionColumn.sen -- partition column related words                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"partitionColumn.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* partitionColumn is used as a kind of word to identify partition columns    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": partitionColumn: ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the partition columns sub folder                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makePartitionColumns ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  find execute ( dic )\n"
    "  table.slots slots.subDic pathPush \\\"columns\\\" :dic drop pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within partitions columns folder                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinPartitionColumns\n"
    "    0 pathPick dic.name \\\"columns\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in partitions columns folder                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInPartitionColumns\n"
    "    withinPartitionColumns if true exit then\n"
    "    EC_NOT_IN_COLUMNS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partitions column folder and push it onto task dictionary         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushPartitionColumns ( -- )\n"
    "\n"
    "    \\\"columns\\\" checkIsWord\n"
    "    not if EC_NO_COLUMNS_DIC false exit then\n"
    "    execute pathPush\n"
    "    true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partition column folder                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitionColumns\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create partition column as a constant                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :partitionColumn ( \\\"<columnName>\\\" )\n"
    "  :constant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check and add a partition column                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAddPartitionColumn ( \\\"<columnName>\\\" \\\"<tableNm>\\\" -- true | eEC false )\n"
    "\n"
    "  locals| tableNm columnNm |\n"
    "\n"
    "  // check we are in the partitions folder\n"
    "  checkInPartitions not if false exit then\n"
    "\n"
    "  // move out of the partitions folder temporarily\n"
    "  popPartitions\n"
    "\n"
    "  // push the table sub folder\n"
    "  tableNm pushTableSub assert\n"
    "\n"
    "  // push the table columns folder\n"
    "  \\\"pushColumns\\\" find execute\n"
    "\n"
    "  // look for the partition column in the table columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should exist in table\n"
    "  not if EC_INVALID_COLUMN false\n"
    "   \\\"popColumns\\\" find execute popTableSub pushPartitions assert exit\n"
    "  then\n"
    "\n"
    "  // pop the columns folder\n"
    "  \\\"popColumns\\\" find execute\n"
    "\n"
    "  // pop the tables sub folder\n"
    "  popTableSub\n"
    "\n"
    "  // push back the partitions folder\n"
    "  pushPartitions assert\n"
    "\n"
    "  // push the partitions sub folder\n"
    "  tableNm pushPartitionSub assert\n"
    "\n"
    "  // push the partitions columns folder\n"
    "  pushPartitionColumns assert // not if false exit then\n"
    "\n"
    "  // look for the column in the partitions columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should not already exist\n"
    "  if EC_DUPLICATE_COLUMN false popPartitionColumns popPartitions exit then\n"
    "\n"
    "  //pop the partition columns folder\n"
    "  popPartitionColumns\n"
    "\n"
    "  // pop the partition sub folder\n"
    "  popPartitionSub\n"
    "\n"
    "  assertInPartitions\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of table partitioning                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitionColumns ( \\\"<tableNm>\\\" -- list )\n"
    "\n"
    "  find execute ( ^tablePtr )\n"
    "\n"
    "  0 0 locals| partitionCols slotsPtr tablePtr |\n"
    "\n"
    "  tablePtr table.slots to slotsPtr\n"
    "  slotsPtr slots.columnCount to partitionCols\n"
    "\n"
    "  \\\"\\\"                             // initial ls string\n"
    "  args.metadata if\n"
    "    partitionCols 0 do\n"
    "      I slotsPtr slots.columnName\n"
    "      \\\"row: ('%v')\\\\n\\\" str.format\n"
    "      str.cat\n"
    "    loop\n"
    "    partitionCols task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "\n"
    "    partitionCols 0 do\n"
    "      I slotsPtr slots.columnName\n"
    "      I 1 + partitionCols < if\n"
    "        swap \\\", \\\" str.cat\n"
    "      then\n"
    "      str.cat\n"
    "    loop\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column (run by all participants)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addPartitionColumn allParticipants 2 checkResult ( \\\"<columnNm>\\\" \\\"<tableNm>\\\" -- <result> )\n"
    "\n"
    "  locals| tableNm columnNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"ADDING PARTITION COLUMN \\\" columnNm str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tp: addingPartitionColumn\n"
    "\n"
    "  // push the partitions sub folder\n"
    "  tableNm pushPartitionSub assert\n"
    "\n"
    "  // push partition columns folder\n"
    "  pushPartitionColumns assert\n"
    "\n"
    "  columnNm columnNm    ( \\\"<columnNm>\\\" \\\"<columnNm>\\\" )\n"
    "  :partitionColumn\n"
    "\n"
    "  // pop partition columns folder\n"
    "  popPartitionColumns\n"
    "\n"
    "  // pop the partitions folder\n"
    "  popPartitionSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the partition                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecPartition allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "  0 locals| tablePtr tableNm |\n"
    "\n"
    "  // get index ptr\n"
    "  tableNm findInCurrent execute to tablePtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // double check we can see the index\n"
    "  //indexPtr find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the partition sub dic and then the columns sub dic\n"
    "  tablePtr pushPartitionSub assert\n"
    "\n"
    "  pushPartitionColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicPath.dump\n"
    "\n"
    "  // iterate contents of columns dictionary \n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    tablePtr                     ( value wordNm ^table )\n"
    "    table.slots slots.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popPartitionColumns\n"
    "\n"
    "  popPartitionSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT partitionColumn.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of partitionModel.sen
  sDefinition =
    "\""
    "\\\"munged partitionModel.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* partitionModel.sen -- Partition Actor Model                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"partitionModel.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* compute the number of partition threads to be created                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": nPartitionThreads ( -- nThreads )\n"
    "\n"
    "  // 1 thread per partition\n"
    "  args.partitionsPerNode locals| nThreads |\n"
    "\n"
    "  //1 exit // temp\n"
    "\n"
    "  nThreads 0 <= if\n"
    "    1\n"
    "  then\n"
    "\n"
    "  nThreads\n"
    " ;\n"
    "\n"
    "//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n"
    "\n"
    "/*\n"
    ": nPartitionThreads ( -- nThreads )\n"
    "\n"
    "  args.regionSize C_1GB / locals| nThreads |\n"
    "\n"
    "  //1 exit // temp\n"
    "\n"
    "  nThreads 0 <= if\n"
    "    1 to nThreads\n"
    "  else\n"
    "    nThreads CORE_COUNT 8 * 10 / > if\n"
    "      CORE_COUNT 8 * 10 / to nThreads\n"
    "    then\n"
    "  then\n"
    "\n"
    "  nThreads\n"
    " ;\n"
    "*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define the N_PARTITION_THREADS constant                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "nPartitionThreads constant N_PARTITION_THREADS\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create and start the partition processing threads                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >partitionThreadNm ( i -- s ) >str \\\"partitionThread\\\" str.prepend ;\n"
    "\n"
    ": :partitionThread ( i -- w ) >partitionThreadNm :thread    ;\n"
    "\n"
    ": startPartitionThreads\n"
    "\n"
    "  0 locals| pPartitionThread |\n"
    "\n"
    "  args.progress if\n"
    "    N_SERVER_THREADS \\\"Partition threads: %v\\\" str.format .\n"
    "  then\n"
    "\n"
    "  args.verbose if\n"
    "    \\\"N_PARTITION_THREADS \\\" .put N_PARTITION_THREADS .put .\\\\n\n"
    "  then\n"
    "\n"
    "  N_PARTITION_THREADS 0 do\n"
    "\n"
    "    // create a thread called partitionThreadI\n"
    "    I :partitionThread execute to pPartitionThread\n"
    "\n"
    "    // set the threads name\n"
    "    I >partitionThreadNm pPartitionThread thread.name!\n"
    "\n"
    "    // set the threads partition no\n"
    "    I pPartitionThread thread.partition!\n"
    "\n"
    "    // set the actor model\n"
    "    AC_PARTITION pPartitionThread thread.actorModel!\n"
    "\n"
    "    // give it a public taskset\n"
    "    I >partitionThreadNm \\\".taskSet\\\" str.cat :taskset execute\n"
    "      pPartitionThread thread.taskset!\n"
    "\n"
    "    // give it a public taskqueue\n"
    "    I >partitionThreadNm \\\".taskQueue\\\" str.cat :taskQueue execute\n"
    "      pPartitionThread thread.taskqueue!\n"
    "\n"
    "    pPartitionThread thread.taskqueue@ \n"
    "      I scheduler::partition partitionScheduler.taskQueue!\n"
    "\n"
    "    I >partitionThreadNm \\\".threadQueue\\\" str.cat :threadQueue execute\n"
    "      I scheduler::partition partitionScheduler.threadQueue!\n"
    "\n"
    "    I >partitionThreadNm \\\".semaphore\\\" str.cat :semaphore execute\n"
    "      I scheduler::partition partitionScheduler.semaphore!\n"
    "\n"
    "    // spawn os thread\n"
    "    pPartitionThread thread.spawn_partition\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create and dispatch task to partition for execution within given partition */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnPartitionTask ( ... nArgs sSeed iPtnNo sTaskNm eTaskKind )\n"
    "\n"
    "  locals| eTaskKind sTaskNm iPtnNo sSeed nArgs |\n"
    "\n"
    "  nArgs sSeed nullptr AC_PARTITION sTaskNm eTaskKind task::new locals| pTask |\n"
    "\n"
    "/*\n"
    "  iPtnNo >partitionThreadNm findActorTaskSet locals| pTaskSet |\n"
    "  pTask pTaskSet taskSet.append\n"
    "*/\n"
    "\n"
    "  pTask iPtnNo scheduler::partition partitionScheduler.enqueueTask\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT partitionModel.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of plan.sen
  sDefinition =
    "\""
    "\\\"munged plan.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* plan.sen -- plan related words                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"plan.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* unpack job and enque on operator queue                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": enqueOnOp ( <<job>> taskNm -- true )\n"
    "\n"
    "tp: enqueOnOp\n"
    "\n"
    "  locals| op.task | ( <<job>> )\n"
    "\n"
    "  // find task and put job onto its jobQueue\n"
    "  op.task find execute >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add call to enque job on operator queue                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addEnqueOnOp ( valset taskNm -- valset )\n"
    "\n"
    "tp: addEnqueOnOp\n"
    "\n"
    "  \\\"enqueOnOp\\\" ( valset taskNm \\\"enqueOnOp\\\" )\n"
    "\n"
    "tp: addingEnqueOnOp\n"
    "\n"
    "  >> ( valset )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pipe to job queue on same node                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue_sameNode ( << [ rb true | false ] profile planId op.task -- )\n"
    "\n"
    "  //\\\"same node\\\" .\n"
    "\n"
    "  locals| op.task | ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // convert job to valset\n"
    "  >>\n"
    "\n"
    "  // find task and put onto it's job queue\n"
    "\n"
    "  op.task find execute >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pipe to job queue on other node                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue_otherNode ( << [ rb true | false ] profile planId op.task nodeNo -- )\n"
    "\n"
    "tp: >>jobQueue_otherNode\n"
    "\n"
    "  //\\\"other node\\\" .\n"
    "\n"
    "  locals| nodeNo op.task | ( << [ rb true | false ] profile plan )\n"
    "\n"
    "  //nodeNo \\\"jobQueue_otherNode NODE %V\\\" str.format .\n"
    "\n"
    "  // translate plan to planId\n"
    "  //plan.id@ ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // convert job to valset\n"
    "  >>\n"
    "\n"
    "  // add enqueOnOp which has op.task as a parameter\n"
    "  op.task addEnqueOnOp ( <<call>> )\n"
    "\n"
    "  // get sender task\n"
    "  nodeNo senderTasks @ ( <<call>> task )\n"
    "\n"
    "  // put on senders job queue\n"
    "  >jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* network aware pipe                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >>jobQueue ( << [ rb true | false ] profile planId op.task -- )\n"
    "\n"
    "  // << false profile plan op.task\n"
    "\n"
    "  // record the op.task\n"
    "  locals| op.task | ( << [ rb true | false ] profile planId )\n"
    "\n"
    "  // partition\n"
    "  0 0 \\\"\\\" locals| profile partitionId nodeNo |\n"
    "\n"
    "  // the profile contains partition information\n"
    "  over to profile\n"
    "\n"
    "  profile str.tailInt\n"
    "  if\n"
    "    // profile has a #partitionId\n"
    "\n"
    "    to partitionId\n"
    "    partitionId grid::toNode to nodeNo\n"
    "\n"
    "    //nodeNo partitionId profile \\\"Profile %v: partition %v on node %v\\\" str.format .\n"
    "\n"
    "    nodeNo grid.thisNode@ ==\n"
    "    if\n"
    "      op.task >>jobQueue_sameNode\n"
    "    else\n"
    "      op.task nodeNo >>jobQueue_otherNode\n"
    "    then\n"
    "\n"
    "    else\n"
    "    // profile is # only\n"
    "\n"
    "    //profile \\\"Profile %v: on originating node\\\" str.format .\n"
    "\n"
    "    grid.thisNode@ 0==\n"
    "    if\n"
    "      op.task >>jobQueue_sameNode\n"
    "    else\n"
    "      op.task nodeNo >>jobQueue_otherNode\n"
    "    then\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* compile the plan                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": compilePlan ( plan -- )\n"
    "\n"
    "  dup task::this task.plan!\n"
    "\n"
    "  dup ( plan plan )\n"
    "\n"
    "  plan.dic task::this task.dicStack dicPath.push ( plan )\n"
    "  //pathDump\n"
    "\n"
    "  //plan.lambda@ .\n"
    "  plan.lambda@ >:\n"
    "\n"
    "  task::this task.dicStack dicPath.drop\n"
    "\n"
    "  0 task::this task.plan!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute the plan                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": executePlan ( plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile |\n"
    "\n"
    "  // trigger triggerOp by piping the plan to it\n"
    "  //<< \\\"triggerOp\\\" thePlan >>\n"
    "  //\\\"triggerOp.task\\\" find execute >jobQueue\n"
    "\n"
    "  << \\\"triggerOp\\\" thePlan plan.id@ \\\"triggerOp.task\\\" >>jobQueue\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* distribute plan (multi-node version)                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": distributePlan allParticipants 1 checkResult ( plan -- true n# true )\n"
    "\n"
    "tp: distributePlan\n"
    "\n"
    "  locals| thePlan |\n"
    "\n"
    "  // add plan to plan list\n"
    "  thePlan planList::addPlan\n"
    "\n"
    "tp: distPlanDone\n"
    "\n"
    "  //\\\"NODE %V\\\" grid.thisNodeName@ str.format .\n"
    "\n"
    "  //planList::show\n"
    "\n"
    "  // compile the plan\n"
    "  thePlan compilePlan\n"
    "\n"
    "tp: cplPlanDone\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* reap plan on all nodes                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": reapPlan allParticipants 1 checkResult ( ??? -- true n# true )\n"
    "\n"
    "tp: reapPlan\n"
    "\n"
    "  \\\": reapPlan\\\" .\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT plan.sen"_Stz
  ;

