    "    1 task::this task.seitf@ seitf.rowsProcessed\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* truncate index                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": truncateIndex_req ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check there is an index of the name\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // truncate index\n"
    "\n"
    "  // find the index\n"
    "  sIndexNm find execute\n"
    "\n"
    "  // truncate the index\n"
    "  index.truncate\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify an index of a table                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyIdx ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "  // ../tables\n"
    "  tp: verifyIdx\n"
    "\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables       not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> assertInTables exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "  popIndexes popTable                                            // ../tables\n"
    "  assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // verify the index\n"
    "  args.metadata if\n"
    "  \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, entries INTEGER)\\\"\n"
    "  metadata!\n"
    "  then\n"
    "\n"
    "  sIndexNm verifyIndex ( )\n"
    "\n"
    "  // set no of rows processed equal to total no of partitions\n"
    "  grid.partitions task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: verifiedIndex\n"
    "\n"
    "  not if <NIP+ERROR> else <SUCCESS> then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify an index of a table                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": verifyIndex_req ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "   verifyIdx\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* visualize index                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": visualizeIndex_req ( \\\"<sIndexNm>\\\" \\\"<sTableNm\\\" -- <R> )\n"
    "  // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "  popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize index\n"
    "\n"
    "  sIndexNm find execute\n"
    "  index.visualize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: dumpedIndex\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_index.sen"_Stz
  ;

