  // munge of requestServer.sen
  sDefinition =
    "\""
    "\\\"munged requestServer.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requestServer.sen -- request processing server                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"requestServer.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the parts                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "queue: requestQueue\n"
    "\n"
    "dic:   tenants\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* copy dictionary path from seitf to this request task                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": getPath\n"
    "\n"
    "  // local for task::this.seitf.dicStack\n"
    "  task::this task.seitf@ seitf.dicStack\n"
    "  locals| pDicStackSEitf |\n"
    "\n"
    "  // local for task::this.dicStack\n"
    "  task::this task.dicStack\n"
    "  locals| pDicStackTask |\n"
    "\n"
    "  // copy the path from seitf dic stack onto data stack\n"
    "  pDicStackSEitf dicPath.depth 0 ?do\n"
    "    I pDicStackSEitf dicPath.pick\n"
    "  loop\n"
    "\n"
    "  // clear this tasks dic stack\n"
    "  pDicStackTask dicPath.dropAll\n"
    "  //dicStackTask dicPath.dump\n"
    "\n"
    "  // copy the path from data stack onto this task dic stack\n"
    "  pDicStackSEitf dicPath.depth 0 ?do\n"
    "    pDicStackTask dicPath.push\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* save dictionary path of this request task back into seitf                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": savePath\n"
    "\n"
    "  // local for task::this.seitf.dicStack\n"
    "  task::this task.seitf@ seitf.dicStack\n"
    "  locals| pDicStackSEitf |\n"
    "\n"
    "  // local for task::this.dicStack\n"
    "  task::this task.dicStack\n"
    "  locals| pDicStackTask |\n"
    "\n"
    "  // copy the path from task dic stack onto data stack\n"
    "  pDicStackTask dicPath.depth 0 ?do\n"
    "    I pDicStackTask dicPath.pick\n"
    "  loop\n"
    "\n"
    "  // clear seitf dic stack\n"
    "  pDicStackSEitf dicPath.dropAll\n"
    "\n"
    "  // copy the path from data stack onto seitf dic stack\n"
    "  pDicStackTask dicPath.depth 0 ?do\n"
    "    pDicStackSEitf dicPath.push\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* process request from SEitf                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": !req \n"
    "\n"
    "tp: !req\n"
    "\n"
    "  // get the request from the task\n"
    "  task::this task.request\n"
    "\n"
    "  valset>\n"
    "\n"
    "tp: valset\n"
    "\n"
    "  // check stack\n"
    "  depth 3 != if \\\"incorrect request stack depth\\\" . process.quit then\n"
    "  0 stack.class CN_INTVAL != if \\\"incorrect request value 0\\\" . process.quit then\n"
    "  1 stack.class CN_STRVAL != if \\\"incorrect request value 1\\\" . process.quit then\n"
    "  2 stack.class CN_STRVAL != if \\\"incorrect request value 2\\\" . process.quit then\n"
    "\n"
    "  // drop the count from stack\n"
    "  drop\n"
    "\n"
    "  // assert the task does not have an seitf\n"
    "  task::this task.seitf@ not assert\n"
    "\n"
    "  // execute the response return address (set SEitf in request task)\n"
    "  >:\n"
    "\n"
    "  // assert the task now has an seitf\n"
    "  task::this task.seitf@ assert\n"
    "\n"
    "  // assert no dictionary path\n"
    "  task::this task.dicStack dicPath.depth not assert\n"
    "\n"
    "  // copy dictionary path from seitf to this request task\n"
    "  getPath\n"
    "\n"
    "  >:   // decode/push the request\n"
    "\n"
    "tp: !req_exit\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send response                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >rsp\n"
    "\n"
    "  // check stack\n"
    "  depth 3 != if \\\"incorrect response stack depth\\\" . process.quit then\n"
    "\n"
    "  0 stack.class CN_INTVAL != if \\\"incorrect response value 0\\\" . process.quit then\n"
    "  1 stack.class CN_INTVAL != if \\\"incorrect response value 1\\\" . process.quit then\n"
    "  2 stack.class CN_STRVAL != if \\\"incorrect response value 2\\\" . process.quit then\n"
    "\n"
    "  >valset\n"
    "\n"
    "  savePath\n"
    "\n"
    "  dicPath.clear\n"
    "\n"
    "  //\\\"rspque\\\" find execute queue.append\n"
    "  task::this task.seitf@ seitf.responseQueue queue.append\n"
    "\n"
    "  // forget the seitf\n"
    "  0 task::this task.seitf!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request processing                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": requestLoop\n"
    "\n"
    "  requestQueue task::this task.jobQueue!\n"
    "\n"
    "  requestServerPrint if\n"
    "    \\\"Request Server running...\\\" .\n"
    "  then\n"
    "\n"
    "  depth 0 != if \\\"request task has grown\\\" . debug::trap then\n"
    "\n"
    "  !req\n"
    "\n"
    "  >rsp\n"
    "\n"
    "  exit\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requestServer.sen"_Stz
  ;

