    "  repeat\n"
    "\n"
    "  loadTimer timer.update\n"
    "\n"
    "  \\\"Load time \\\" .put\n"
    "  loadTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "\n"
    "  reg7 loadTimer timer.secs / .put \\\" r/s\\\" .put .\\\\n\n"
    "\n"
    "  reg0 file.close\n"
    "\n"
    "  reg0 file.delete\n"
    "\n"
    "  reg.pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* loop test                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sld2\n"
    "\n"
    "  10000000 0\n"
    "  do\n"
    "    I 1000000 % not if I . then\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT streamLoader.sen"_Stz
  ;

