  // munge of table.sen
  sDefinition =
    "\""
    "\\\"munged table.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* table.sen -- table related words                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"table.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* table is used as a kind of word to identify tables                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table ;\n"
    "\n"
    "//: makeTables pathPush \\\"tables\\\" :dic tick folder swap execute dic.kind! pathDrop ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tables folder under given named schema                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTables ( \\\"<schemaNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLES FOR SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"tables\\\"     ( dic \\\"tables\\\" )\n"
    "  swap         ( \\\"tables\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tableNm folder under tables                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTableDic ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLE DIC \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  0 pathPick\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "\n"
    ": isTable word.kind@ tick table eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name from input stream (doesnt leave table on stk)    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_table allot\n"
    "  word.this >body object.magic!\n"
    "  CN_TABLE word.this >body object.class!\n"
    "  word.this >body table.init\n"
    "  true word.this >body object.wordbody!\n"
    "  tick table word.this word.kind!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name on the stack (leaves table on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :table\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_table allot\n"
    "  word.this >body object.magic!\n"
    "  CN_TABLE word.this >body object.class!\n"
    "  word.this >body table.init\n"
    "  true word.this >body object.wordbody!\n"
    "  tick table word.this word.kind!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path ends in tables                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTables ( -- t|f )\n"
    "\n"
    "  0 pathPick dic.name \\\"tables\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is tables                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInTables ( -- t|f )\n"
    "\n"
    "  withinTables assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is tables                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTables ( -- t|f )\n"
    "\n"
    "  withinTables if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if this task dic path is same name as argument                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  assert::stack_1+\n"
    "  CN_STRVAL assert::class_0\n"
    "\n"
    "  // assert dictionary path\n"
    "  task::this task.dicStack dicPath.depth assert\n"
    "\n"
    "  0 pathPick dic.name str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check top of task dictionary stack is given table name                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInTable ( \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  withinTable if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLE false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTable ( \\\"<tableNm>\\\" -- \\\"<tableNm>\\\" true | errorCode false )\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" \\\"<tableNm>\\\" )\n"
    "\n"
    "  find ( \\\"<tableNm>\\\" ^w:table )\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "  not ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    drop ( )\n"
    "    EC_NO_SUCH_TABLE false ( errorCode false )\n"
    "  exit\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "\n"
    "  word.kind@ ( \\\"<tableNm>\\\" ^w:table ^word )\n"
    "  tick table ( \\\"<tableNm>\\\" ^w:table ^word ^word )\n"
    "  eql ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    drop ( \\\"<tableNm>\\\" )\n"
    "    true ( \\\"<tableNm>\\\" true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  drop ( \\\"<tableNm>\\\" )\n"
    "  drop ( )\n"
    "  EC_NOT_A_TABLE false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is not a table                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotTable ( \\\"<wordNm\\\" -- t|f )\n"
    "  dup findInCurrent not if true exit then\n"
    "  EC_TABLE_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check there is a table folder                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTableFolder  ( \\\"<tableName>\\\" -- )\n"
    "  findInCurrent not if EC_NO_SUCH_TABLE false exit then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table folder and push it onto task dictionary                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushTable ( \\\"<tableName>\\\" -- )\n"
    "  find execute pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popTable\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table sub folder and push it onto task dictionary                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushTableSub ( \\\"<tableName>\\\" -- )\n"
    "  checkIsTable not if EC_NO_SUCH_TABLE false exit then\n"
    "  find execute table.subDic pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table sub folder                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popTableSub\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get and inc table reference and put into task.seitf.currentTable           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": getTableRef ( \\\"<tableNm>\\\" -- <R> )\n"
    "\n"
    "  dup checkInTable not if false exit then\n"
    "\n"
    "  checkIsTable not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  find execute ( table )\n"
    "\n"
    "  task::this task.seitf@ seitf.tableRef\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dec and return table reference and clear task.seitf.currentTable           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": returnTableRef ( )\n"
    "\n"
    "  task::this task.seitf@ seitf.tableDeref\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* any outstanding table references                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableInUse ( \\\"<tableNm>\\\" -- <R> )\n"
    "\n"
    "  find execute\n"
    "\n"
    "  table.ref\n"
    "  if true else false then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable table                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeTable ( \\\"<tableNm>\\\" -- \\\"<tableNm>\\\" true | \\\"<tableNm>\\\" errorCode false )\n"
    "\n"
    "  checkInTables   not if false exit then\n"
    "  checkIsNotTable not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable table folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveTable ( \\\"<tableNm>\\\" -- \\\"<tableNm>\\\" true | \\\"<tableNm>\\\" errorCode false )\n"
    "\n"
    "  checkInTables not if false exit then ( \\\"<tableNm>\\\" )\n"
    "\n"
    "  dup checkIsWord not if EC_NO_SUCH_TABLE false exit then ( \\\"<tableNm>\\\" )\n"
    "  drop\n"
    "\n"
    "  // push table folder\n"
    "  dup pushTable assert\n"
    "\n"
    "  checkIsTable not if popTable false exit then ( \\\"<tableNm>\\\" )\n"
    "  dup tableInUse if popTable EC_TABLE_IN_USE false exit then ( \\\"<tableNm>\\\" )\n"
    "\n"
    "  // opo table folder\n"
    "  popTable\n"
    "\n"
    "  true ( \\\"<tableNm>\\\" true )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get size of table                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeTable ( -- \\\"<size>\\\" )\n"
    "\n"
    "  \\\"indexes\\\" find execute pathPush\n"
    "  \\\"hidden\\\" \\\"sizeIndex\\\" find execute  >str\n"
    "  pathDrop\n"
    "\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    ": dumpTable ( \\\"<tableNm>\\\" )\n"
    "\n"
    "  find execute ( table )\n"
    "\n"
    "  \\\"__row_cursor\\\" find dup\n"
    "  if\n"
    "  else\n"
    "    drop\n"
    "    \\\"__row_cursor\\\" :selCursor\n"
    "  then\n"
    "  execute\n"
    "\n"
    "  >r\n"
    "  // r0 ^selCursor\n"
    "\n"
    "  r0 selCursor.table!\n"
    "  grid.slots 0\n"
    "  do\n"
    "    // r2 ^selCursor\n"
    "    I r2 selCursor.begin\n"
    "    r2 selCursor.first\n"
    "\n"
    "    begin\n"
    "\n"
    "      while\n"
    "\n"
    "      r2 selCursor.get\n"
    "      .\n"
    "      r2 selCursor.next\n"
    "\n"
    "      repeat\n"
    "\n"
    "      r2 selCursor.end\n"
    "  loop\n"
    "\n"
    "  rdrop\n"
    "\n"
    "  \\\"__row_cursor\\\" find word.forget\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* truncate table                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": truncateTable ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  find execute ( table )\n"
    "\n"
    "  table.truncate\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyze a table                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeTable allParticipants 1 returnResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "tp: analyzeTable\n"
    "\n"
    "  find execute\n"
    "  0 // not detailed\n"
    "  swap\n"
    "  table.analyze\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyze a table (detail analysis)                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": danalyzeTable allParticipants 1 returnResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: danalyzeTable\n"
    "\n"
    "  find execute\n"
    "  1 // detailed\n"
    "  swap\n"
    "  table.analyze\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a table (run by participant)                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTable allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "tp: makingTable\n"
    "  0 locals| indexPtr sTableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  sTableNm \\\"MAKING TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  sTableNm makeTableDic\n"
    "\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm \\\"makeIndexes\\\" find execute\n"
    "\n"
    "  sTableNm \\\"makePartitions\\\" find execute\n"
    "\n"
    "  sTableNm :table ( ^table ) drop\n"
    "\n"
    "  // make partition columns\n"
    "  sTableNm \\\"makePartitionColumns\\\" find execute\n"
    "\n"
    "  // forward reference :-(\n"
    "  sTableNm \\\"makeColumns\\\" find execute\n"
    "\n"
    "  // create the hidden index for the row data\n"
    "  sTableNm \\\"hidden\\\" \\\"make_index\\\" find execute\n"
    "\n"
    "  // make the index as hidden\n"
    "  \\\"indexes\\\" find execute pathPush\n"
    "  \\\"hidden\\\" findInCurrent execute to indexPtr\n"
    "  true indexPtr index.isHidden!\n"
    "\n"
    "  // now add a column to the hidden index\n"
    "  \\\"hidden_column\\\" \\\"hidden\\\"\n"
    "  \\\"add_indexColumn\\\" find execute\n"
    "\n"
    "  // create the column vector of the index\n"
    "  indexPtr index.subDic pathPush\n"
    "\n"
    "  \\\"columns\\\" find execute pathPush\n"
    "\n"
    "  \\\"integer\\\" \\\"hidden_column\\\" indexPtr index.createColumnVec\n"
    "\n"
    "  pathDrop  // step out of columns\n"
    "  pathDrop  // step out of subdic\n"
    "  pathDrop  // step out of indexes\n"
    "\n"
    "  // store the hidden index in the table\n"
    "  indexPtr sTableNm find execute table.hiddenIndex!\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a table folder                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeTable allParticipants 1 checkResult ( \\\"<tableNm>\\\" -- true n# true )\n"
    "\n"
    "tp: removeTable\n"
    "\n"
    "  locals| tableNm |\n"
    "\n"
    "  tableNm pushTable assert\n"
    "  tableNm find execute ( ^table )\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // drop all rows\n"
    "  //dup table.truncate ( ^table )\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // drop all indexes\n"
    "  \\\"indexes\\\" find execute pathPush\n"
    "\n"
    "  // iterate thru all indexes and tidyUp\n"
    "  0 pathPick dic.lastWord dup\n"
    "    iterate                        // setup iteration of words\n"
    "    object@ word.name\n"
    "   \n"
    "    // forward reference :-(\n"
    "    \\\"indexTidyUp\\\" find execute\n"
    "\n"
    "    object@ word.prev object!     // step backwards thru words\n"
    "  next\n"
    "\n"
    "  pathDrop\n"
    "\n"
    "  // forget the indexes in the indexes dictionary\n"
    "  \\\"indexes\\\" find execute forgetAll\n"
    "\n"
    "  // forget the indexes dictionary itself\n"
    "  \\\"indexes\\\" :forget\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // drop all partition keys etc\n"
    "\n"
    "  // forget all column names in the columns dictionary of partitions sub-dictionary\n"
    "  dup table.slots slots.subDic\n"
    "  pathPush\n"
    "  \\\"columns\\\" find execute forgetAll\n"
    "  pathDrop\n"
    "\n"
    "  dup table.slots slots.subDic forgetAll\n"
    "\n"
    "  // forget the partitions in the partitions dictionary\n"
    "  \\\"partitions\\\" find execute forgetAll\n"
    "\n"
    "  // forget the partitions dictionary itself\n"
    "  \\\"partitions\\\" :forget\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // drop all table columns etc\n"
    "  // forget all column names in the columns dictionary of table sub-dictionary\n"
    "  dup table.subDic\n"
    "  pathPush\n"
    "    \\\"columns\\\" find execute forgetAll\n"
    "  pathDrop\n"
    "\n"
    "  // forget the columns dictionary in the table sub-dictionary\n"
    "  table.subDic forgetAll\n"
    "\n"
    "  tableNm :forget\n"
    "\n"
    "  popTable\n"
    "\n"
    "  tableNm :forget\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set no of subloaders in table on each participant                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setSubLoaders allParticipants 2 checkResult ( \\\"<tableNm\\\" subLoaders -- true n# true )\n"
    "\n"
    "  locals| sTableNm iSubLoaders |\n"
    "\n"
    "  iSubLoaders\n"
    "  sTableNm find execute\n"
    "  table.subLoaders\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT table.sen"_Stz
  ;

  vCompileConstant(sDefinition);

