  // munge of tenant.sen
  sDefinition =
    "\""
    "\\\"munged tenant.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* tenant.sen -- tenant related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"tenant.sen\\\" .verbose\n"
    "\n"
    ": tenant ;\n"
    "\n"
    ": :tenant\n"
    "    :dic\n"
    "         //dup tick tenant swap word.kind!\n"
    "         dup tick tenant swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinTenants\n"
    "    0 pathPick dic.name \\\"tenants\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInTenants\n"
    "    withinTenants if true exit then\n"
    "    EC_NOT_IN_TENANTS false\n"
    " ;\n"
    "/*\n"
    ": checkIsTenant ( word )\n"
    "\n"
    "    dup word.kind@ tick folder eql if true exit then\n"
    "    dup execute dic.kind@ tick tenant eql if true exit then\n"
    "    drop\n"
    "    EC_NOT_A_TENANT false\n"
    " ;\n"
    "*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a tenant folder                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsTenant ( word )\n"
    "\n"
    "  dup word.kind@ tick folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "  dup execute dic.kind@ tick tenant eql if true exit then\n"
    "  EC_NOT_A_TENANT false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is not already a tenant folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotTenant ( word )\n"
    "  dup findInCurrent not if true exit then\n"
    "  EC_TENANT_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable tenant folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeTenant ( \\\"<tenantNm>\\\" -- \\\"<tenantNm>\\\" true | \\\"<tenantNm>\\\" errorCode false )\n"
    "\n"
    "  checkInTenants    not if false exit then\n"
    "  checkIsNotTenant  not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable tenant folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveTenant ( \\\"<tenantNm>\\\" -- \\\"<tenantNm>\\\" true | \\\"<tenantNm>\\\" errorCode false )\n"
    "\n"
    "  dup ( \\\"<tenantNm>\\\" \\\"<tenantNm>\\\" )\n"
    "\n"
    "  checkInTenants  not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkIsWord     not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkIsTenant   not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkIsEmpty    not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "  checkNotUsed    not if false exit then ( \\\"<tenantNm>\\\" word )\n"
    "\n"
    "  drop ( \\\"<tenantNm>\\\" )\n"
    "\n"
    "  true ( \\\"<tenantNm>\\\" true )\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tenant folder (run by participant)                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTenant allParticipants 1 checkResult ( \\\"<tenantNm>\\\" -- true n# true )\n"
    "\n"
    "tp: makingTenant\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "    dup ( \\\"<tenantNm>\\\" \\\"<tenantNm>\\\" )\n"
    "\n"
    "    :tenant ( \\\"<tenantNm>\\\" ^tenant )\n"
    "\n"
    "    drop ( \\\"<tenantNm>\\\" )\n"
    "\n"
    "    makeCatalogs ( )\n"
    "\n"
    "    true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a tenant folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeTenant allParticipants 1 checkResult ( \\\"<tenantNm>\\\" -- true n# true )\n"
    "\n"
    "tp: removetenant\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"REMOVING TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  :forget ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT tenant.sen"_Stz
  ;

  vCompileConstant(sDefinition);

